  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_enum_status` CHECK (`status` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'BLOCKED', 'REVIEW_REQUIRED')),
  `config` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_config` CHECK (json_valid(`config`)),
  `started_at` INTEGER,
  `finished_at` INTEGER,
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 255),
  `failure_detail` TEXT COLLATE NOCASE,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_pipeline_runs_20` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_pipeline_runs_21` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_t_pipeline_runs_video_id` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`)
) STRICT;
CREATE TABLE `pipeline_steps` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `step_name` TEXT COLLATE NOCASE NOT NULL CHECK (step_name IN ('VALIDATE','TRANSCODE','SHOTS','DETECT','TRACK','IDENTIFY','EVENTS','TACTICS','INDEX','QUALITY','FINISH')) CONSTRAINT `ck_len_step_name` CHECK (length(`step_name`) <= 255),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_enum_status` CHECK (`status` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'BLOCKED', 'REVIEW_REQUIRED')),
  `attempt` INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  `progress` REAL NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100),
  `output_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_output_asset_id` CHECK (length(`output_asset_id`) <= 36),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `error_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_error_code` CHECK (length(`error_code`) <= 255),
  `started_at` INTEGER,
  `completed_at` INTEGER,
  UNIQUE (`run_id`, `step_name`),
  CONSTRAINT `fk_pipeline_steps_22` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pipeline_steps_23` FOREIGN KEY (`output_asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_pipeline_steps_24` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`)
) STRICT;
CREATE TABLE `job_events` (
