  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `step_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_step_id` CHECK (length(`step_id`) <= 36),
  `event_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_event_type` CHECK (length(`event_type`) <= 255),
  `payload` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_payload` CHECK (json_valid(`payload`)),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_job_events_25` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_job_events_26` FOREIGN KEY (`step_id`) REFERENCES `pipeline_steps` (`id`)
) STRICT;
CREATE TABLE `evidence_records` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `pipeline_run_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_pipeline_run_id` CHECK (length(`pipeline_run_id`) <= 36),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_state` CHECK (`state` IN ('DETECTED', 'INFERRED', 'CONFIRMED', 'NOT_MEASURED')),
  `source_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_source_type` CHECK (length(`source_type`) <= 255),
  `source_ref` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_source_ref` CHECK (length(`source_ref`) <= 255),
  `confidence` REAL CHECK (confidence BETWEEN 0 AND 1),
  `reviewer_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_reviewer_id` CHECK (length(`reviewer_id`) <= 36),
  `reviewed_at` INTEGER,
  `notes` TEXT COLLATE NOCASE,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_evidence_records_27` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_evidence_records_28` FOREIGN KEY (`pipeline_run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_evidence_records_29` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
  CONSTRAINT `fk_evidence_records_30` FOREIGN KEY (`reviewer_id`) REFERENCES `users` (`id`),
  CHECK (state <> 'CONFIRMED' OR reviewer_id IS NOT NULL)
) STRICT;
CREATE TABLE `rights_grants` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_asset_id` CHECK (length(`asset_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `rights_state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'UNKNOWN' CONSTRAINT `ck_enum_rights_state` CHECK (`rights_state` IN ('UNKNOWN', 'ANALYSIS_ONLY', 'INTERNAL', 'EXPORT_ALLOWED', 'PUBLIC', 'EXPIRED')),
  `allowed_uses` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_array()) CONSTRAINT `ck_json_allowed_uses` CHECK (json_valid(`allowed_uses`)),
  `territory_codes` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_array()) CONSTRAINT `ck_json_territory_codes` CHECK (json_valid(`territory_codes`)),
  `valid_from` INTEGER,
  `valid_until` INTEGER,
  `guardian_consent_state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'NOT_APPLICABLE' CHECK (guardian_consent_state IN('NOT_APPLICABLE','PENDING','VERIFIED','REVOKED')) CONSTRAINT `ck_len_guardian_consent_state` CHECK (length(`guardian_consent_state`) <= 255),
  `evidence_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_asset_id` CHECK (length(`evidence_asset_id`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_rights_grants_31` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_rights_grants_32` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_rights_grants_33` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_rights_grants_34` FOREIGN KEY (`evidence_asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_t_rights_grants_evidence_asset_id` FOREIGN KEY (`evidence_asset_id`, `organization_id`) REFERENCES `assets` (`id`, `organization_id`),
  CONSTRAINT `fk_t_rights_grants_asset_id` FOREIGN KEY (`asset_id`, `organization_id`) REFERENCES `assets` (`id`, `organization_id`),
  CONSTRAINT `fk_t_rights_grants_video_id` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CHECK (valid_until IS NULL OR valid_from IS NULL OR valid_until>valid_from)
) STRICT;
CREATE TABLE `audit_events` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT,
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `actor_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_actor_id` CHECK (length(`actor_id`) <= 36),
  `action` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_action` CHECK (length(`action`) <= 255),
  `entity_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_entity_type` CHECK (length(`entity_type`) <= 255),
  `entity_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_entity_id` CHECK (length(`entity_id`) <= 36),
  `request_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_request_id` CHECK (length(`request_id`) <= 255),
  `before_state` TEXT COLLATE NOCASE CONSTRAINT `ck_json_before_state` CHECK (json_valid(`before_state`)),
  `after_state` TEXT COLLATE NOCASE CONSTRAINT `ck_json_after_state` CHECK (json_valid(`after_state`)),
  `occurred_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `actor_kind` TEXT COLLATE NOCASE NOT NULL DEFAULT 'USER' CONSTRAINT `ck_len_actor_kind` CHECK (length(`actor_kind`) <= 16),
  `actor_service` TEXT COLLATE NOCASE CONSTRAINT `ck_len_actor_service` CHECK (length(`actor_service`) <= 100),
  UNIQUE (`id`, `organization_id`),
  CONSTRAINT `fk_audit_events_35` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_audit_events_36` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_audit_actor_kind` CHECK (`actor_kind` IN ('USER', 'SYSTEM', 'SERVICE')),
  CONSTRAINT `ck_audit_user_has_actor` CHECK (`actor_kind` <> 'USER' OR `actor_id` IS NOT NULL),
  CONSTRAINT `ck_audit_actor_named` CHECK ((`actor_kind` = 'USER') = (`actor_service` IS NULL)),
  CONSTRAINT `ck_audit_action_format` CHECK ((`action` GLOB '[a-z]*' AND `action` GLOB '*.*' AND `action` NOT GLOB '*[^a-z0-9_.]*' AND `action` NOT GLOB '*.[^a-z]*' AND `action` NOT GLOB '*.'))
) STRICT;
CREATE TABLE `video_frame_index` (
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `frame_index` INTEGER NOT NULL CHECK (frame_index>=0),
