  CONSTRAINT `fk_video_frame_index_38` FOREIGN KEY (`shot_id`) REFERENCES `video_shots` (`id`)
) STRICT;
CREATE TABLE `detection_batches` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `model_version_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `start_frame` INTEGER NOT NULL,
  `end_frame` INTEGER NOT NULL,
  `payload_asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_payload_asset_id` CHECK (length(`payload_asset_id`) <= 36),
  `checksum` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_checksum` CHECK (length(`checksum`) <= 64),
  `detection_count` INTEGER NOT NULL CHECK (detection_count>=0),
  CONSTRAINT `fk_detection_batches_39` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_detection_batches_40` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
  CONSTRAINT `fk_detection_batches_41` FOREIGN KEY (`payload_asset_id`) REFERENCES `assets` (`id`),
  CHECK (end_frame>=start_frame)
) STRICT;
CREATE TABLE `tracks` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `internal_track_number` INTEGER NOT NULL,
  `class_name` TEXT COLLATE NOCASE NOT NULL CHECK (class_name IN ('PLAYER','GOALKEEPER','REFEREE','BALL','OTHER')) CONSTRAINT `ck_len_class_name` CHECK (length(`class_name`) <= 255),
  `first_pts_us` INTEGER NOT NULL,
  `last_pts_us` INTEGER NOT NULL,
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'ACTIVE' CHECK (status IN('ACTIVE','OCCLUDED','LEFT_FRAME','ENDED','REVIEW_REQUIRED')) CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 255),
  `identity_state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'UNRESOLVED' CONSTRAINT `ck_enum_identity_state` CHECK (`identity_state` IN ('UNRESOLVED', 'CANDIDATE', 'CONFIRMED', 'REJECTED', 'CONFLICT')),
  `quality_score` REAL CHECK (quality_score BETWEEN 0 AND 1),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `shot_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_shot_id` CHECK (length(`shot_id`) <= 36),
  `observation_count` INTEGER NOT NULL DEFAULT 0,
  `mean_confidence` REAL,
  UNIQUE (`run_id`, `internal_track_number`),
  CONSTRAINT `fk_tracks_42` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_tracks_43` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_tracks_shot` FOREIGN KEY (`shot_id`) REFERENCES `video_shots` (`id`),
  CHECK (last_pts_us >= first_pts_us),
  CONSTRAINT `ck_tracks_class` CHECK (`class_name` IN ('PERSON', 'PLAYER', 'GOALKEEPER', 'REFEREE', 'BALL', 'OTHER')),
  CONSTRAINT `ck_tracks_counts` CHECK (`observation_count` >= 0 AND (`mean_confidence` IS NULL OR `mean_confidence` BETWEEN 0 AND 1))
) STRICT;
CREATE TABLE `track_segments` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `shot_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_shot_id` CHECK (length(`shot_id`) <= 36),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `observation_asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_observation_asset_id` CHECK (length(`observation_asset_id`) <= 36),
  `interpolation_policy` TEXT COLLATE NOCASE NOT NULL DEFAULT 'NONE' CHECK (interpolation_policy IN('NONE','SHORT_GAP_LINEAR','KALMAN','REVIEWED')) CONSTRAINT `ck_len_interpolation_policy` CHECK (length(`interpolation_policy`) <= 255),
  `gap_count` INTEGER NOT NULL DEFAULT 0 CHECK (gap_count >= 0),
  `quality_score` REAL CHECK (quality_score BETWEEN 0 AND 1),
  CONSTRAINT `fk_track_segments_44` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_track_segments_45` FOREIGN KEY (`shot_id`) REFERENCES `video_shots` (`id`),
  CONSTRAINT `fk_track_segments_46` FOREIGN KEY (`observation_asset_id`) REFERENCES `assets` (`id`),
  CHECK (end_pts_us>start_pts_us)
) STRICT;
CREATE TABLE `track_observations` (
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `frame_index` INTEGER NOT NULL,
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `pts_us` INTEGER NOT NULL,
  `bbox_x` REAL NOT NULL CHECK (bbox_x BETWEEN 0 AND 1),
  `bbox_y` REAL NOT NULL CHECK (bbox_y BETWEEN 0 AND 1),
  `bbox_w` REAL NOT NULL CHECK (bbox_w>0 AND bbox_w<=1),
  `bbox_h` REAL NOT NULL CHECK (bbox_h>0 AND bbox_h<=1),
  `detector_confidence` REAL CHECK (detector_confidence BETWEEN 0 AND 1),
  `association_confidence` REAL CHECK (association_confidence BETWEEN 0 AND 1),
  `observation_state` TEXT COLLATE NOCASE NOT NULL CHECK (observation_state IN ('DETECTED','PREDICTED','INTERPOLATED','REVIEWED')) CONSTRAINT `ck_len_observation_state` CHECK (length(`observation_state`) <= 255),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  PRIMARY KEY (`video_id`, `frame_index`, `track_id`),
  CONSTRAINT `fk_track_observations_47` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_track_observations_48` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_track_observations_49` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
  CONSTRAINT `fk_track_observations_50` FOREIGN KEY (`video_id`, `frame_index`) REFERENCES `video_frame_index` (`video_id`, `frame_index`),
  CHECK (bbox_x+bbox_w<=1.00001),
  CHECK (bbox_y+bbox_h<=1.00001)
) STRICT;
CREATE TABLE `track_identity_candidates` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `match_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_match_id` CHECK (length(`match_id`) <= 36),
  `score` REAL NOT NULL CHECK (score BETWEEN 0 AND 1),
  `evidence` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_evidence` CHECK (json_valid(`evidence`)),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`track_id`, `player_id`, `model_version_id`),
  CONSTRAINT `fk_track_identity_candidates_51` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_track_identity_candidates_52` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_track_identity_candidates_53` FOREIGN KEY (`match_id`) REFERENCES `matches` (`id`),
  CONSTRAINT `fk_track_identity_candidates_54` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`)
) STRICT;
CREATE TABLE `track_identity_decisions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_state` CHECK (`state` IN ('UNRESOLVED', 'CANDIDATE', 'CONFIRMED', 'REJECTED', 'CONFLICT')),
  `decided_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `basis` TEXT COLLATE NOCASE NOT NULL CHECK (basis IN('HUMAN','AUTO_POLICY','REGISTRY')) CONSTRAINT `ck_len_basis` CHECK (length(`basis`) <= 255),
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  `decided_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `supersedes_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_supersedes_id` CHECK (length(`supersedes_id`) <= 36),
  `reason` TEXT COLLATE NOCASE,
  CONSTRAINT `uq_tid_id_track` UNIQUE (`id`, `track_id`),
  CONSTRAINT `uq_tid_id_track_player` UNIQUE (`id`, `track_id`, `player_id`),
  CONSTRAINT `uq_tid_supersedes_once` UNIQUE (`supersedes_id`),
  CONSTRAINT `fk_track_identity_decisions_55` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_track_identity_decisions_56` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_track_identity_decisions_57` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_track_identity_decisions_58` FOREIGN KEY (`evidence_id`) REFERENCES `evidence_records` (`id`),
  CONSTRAINT `fk_track_identity_decisions_59` FOREIGN KEY (`supersedes_id`) REFERENCES `track_identity_decisions` (`id`),
  CONSTRAINT `fk_tid_supersedes_same_track` FOREIGN KEY (`supersedes_id`, `track_id`) REFERENCES `track_identity_decisions` (`id`, `track_id`),
  CHECK (state <> 'CONFIRMED' OR player_id IS NOT NULL),
  CHECK (basis <> 'HUMAN' OR decided_by IS NOT NULL)
) STRICT;
CREATE TABLE `pitch_calibrations` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `shot_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_shot_id` CHECK (length(`shot_id`) <= 36),
  `start_pts_us` INTEGER NOT NULL,
