  CONSTRAINT `fk_pitch_calibrations_61` FOREIGN KEY (`shot_id`) REFERENCES `video_shots` (`id`),
  CONSTRAINT `fk_pitch_calibrations_62` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
  CONSTRAINT `fk_pitch_cal_request` FOREIGN KEY (`request_id`) REFERENCES `pitch_calibration_requests` (`id`) ON DELETE CASCADE,
  CHECK (end_pts_us>start_pts_us)
) STRICT;
CREATE TABLE `event_candidates` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `event_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_event_type` CHECK (length(`event_type`) <= 255),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `primary_track_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_primary_track_id` CHECK (length(`primary_track_id`) <= 36),
  `secondary_track_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_secondary_track_id` CHECK (length(`secondary_track_id`) <= 36),
  `confidence` REAL CHECK (confidence BETWEEN 0 AND 1),
  `evidence_state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'DETECTED' CONSTRAINT `ck_enum_evidence_state` CHECK (`evidence_state` IN ('DETECTED', 'INFERRED', 'CONFIRMED', 'NOT_MEASURED')),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  `features` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_features` CHECK (json_valid(`features`)),
  `ball_track_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_ball_track_id` CHECK (length(`ball_track_id`) <= 36),
  `kit_group` INTEGER,
  CONSTRAINT `fk_event_candidates_63` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_event_candidates_64` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_event_candidates_65` FOREIGN KEY (`primary_track_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_event_candidates_66` FOREIGN KEY (`secondary_track_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_event_candidates_67` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
  CONSTRAINT `fk_event_candidates_68` FOREIGN KEY (`evidence_id`) REFERENCES `evidence_records` (`id`),
  CONSTRAINT `fk_event_candidates_ball` FOREIGN KEY (`ball_track_id`) REFERENCES `ball_tracks` (`id`),
  CHECK (end_pts_us>=start_pts_us)
) STRICT;
CREATE TABLE `event_decisions` (
