  CONSTRAINT `fk_metric_values_75` FOREIGN KEY (`evidence_id`) REFERENCES `evidence_records` (`id`),
  CONSTRAINT `fk_metric_values_76` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
