  `project_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_project_id` CHECK (length(`project_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 255),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'DRAFT' CHECK (status IN('DRAFT','READY','RENDERING','PUBLISHED','BLOCKED','ARCHIVED')) CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 255),
  `version` INTEGER NOT NULL DEFAULT 1,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `player_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `run_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `aspect` TEXT COLLATE NOCASE NOT NULL DEFAULT '16:9' CONSTRAINT `ck_len_aspect` CHECK (length(`aspect`) <= 8),
  `settings` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_settings` CHECK (json_valid(`settings`)),
  `removed_at` INTEGER,
  `removed_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_removed_by` CHECK (length(`removed_by`) <= 36),
  `source` TEXT COLLATE NOCASE NOT NULL DEFAULT 'MATCH' CONSTRAINT `ck_enum_source` CHECK (`source` IN ('MATCH', 'ALL_MATCHES')),
  `cross_match_length_s` INTEGER,
  `best_moments_rule_version` TEXT COLLATE NOCASE CONSTRAINT `ck_len_best_moments_rule_version` CHECK (length(`best_moments_rule_version`) <= 16),
  UNIQUE (`id`, `organization_id`),
  CONSTRAINT `fk_reel_projects_77` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_reel_projects_78` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`),
  CONSTRAINT `fk_reel_projects_79` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_reel_projects_80` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_t_reel_projects_project_id` FOREIGN KEY (`project_id`, `organization_id`) REFERENCES `projects` (`id`, `organization_id`),
  CONSTRAINT `fk_t_reel_projects_video_id` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_reel_projects_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_reel_projects_run` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_reel_removed_by` FOREIGN KEY (`removed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_reel_removed_pair` CHECK ((`removed_at` IS NULL) = (`removed_by` IS NULL)),
  CONSTRAINT `ck_reel_projects_aspect` CHECK (`aspect` IN ('16:9', '9:16', '1:1', '4:5')),
  CONSTRAINT `ck_reel_projects_source` CHECK (
    (`source` = 'MATCH' AND `video_id` IS NOT NULL AND `cross_match_length_s` IS NULL AND `best_moments_rule_version` IS NULL)
    OR (`source` = 'ALL_MATCHES' AND `video_id` IS NULL AND `run_id` IS NULL AND `cross_match_length_s` IN (90, 180, 300)
        AND `best_moments_rule_version` IS NOT NULL))
) STRICT;
