  `review_state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'PENDING' CHECK (review_state IN('PENDING','APPROVED','REJECTED','RED')) CONSTRAINT `ck_len_review_state` CHECK (length(`review_state`) <= 255),
