  CONSTRAINT `ck_reel_clips_effect_kind` CHECK (`effect_kind` IN ('NONE', 'SLOW', 'FREEZE', 'RAMP')),
  CONSTRAINT `ck_reel_clips_effect_moment` CHECK ((`effect_kind` IN ('FREEZE', 'RAMP')) = (`effect_at_us` IS NOT NULL)),
  CONSTRAINT `ck_reel_clips_effect_hold` CHECK (`effect_hold_ms` BETWEEN 0 AND 3000 AND (`effect_kind` = 'FREEZE') = (`effect_hold_ms` > 0)),
  CONSTRAINT `ck_reel_clips_speed_range` CHECK (`playback_speed` BETWEEN 0.25 AND 1 AND (`effect_kind` IN ('SLOW', 'RAMP')) = (`playback_speed` < 1)),
  CONSTRAINT `ck_reel_clips_fx_object` CHECK (`clip_fx` IS NULL OR json_type(`clip_fx`) = 'object')
