  CONSTRAINT `fk_t_comments_reel_id` FOREIGN KEY (`reel_id`, `organization_id`) REFERENCES `reel_projects` (`id`, `organization_id`),
  CONSTRAINT `fk_comments_share_link` FOREIGN KEY (`share_link_id`) REFERENCES `share_links` (`id`),
