CREATE TABLE `outbox_events` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT,
  `aggregate_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_aggregate_type` CHECK (length(`aggregate_type`) <= 255),
  `aggregate_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_aggregate_id` CHECK (length(`aggregate_id`) <= 36),
  `event_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_event_type` CHECK (length(`event_type`) <= 255),
  `event_payload` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_event_payload` CHECK (json_valid(`event_payload`)),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `claimed_at` INTEGER,
  `delivered_at` INTEGER,
  `attempt_count` INTEGER NOT NULL DEFAULT 0,
  `organization_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `dedupe_key` TEXT COLLATE NOCASE CONSTRAINT `ck_len_dedupe_key` CHECK (length(`dedupe_key`) <= 191),
  `available_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `last_error` TEXT COLLATE NOCASE CONSTRAINT `ck_len_last_error` CHECK (length(`last_error`) <= 1000),
  `claim_token` TEXT COLLATE NOCASE CONSTRAINT `ck_len_claim_token` CHECK (length(`claim_token`) <= 36),
  `lease_expires_at` INTEGER,
  `dead_lettered_at` INTEGER,
  CONSTRAINT `uq_outbox_dedupe` UNIQUE (`dedupe_key`),
  CONSTRAINT `fk_outbox_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `ck_outbox_attempts` CHECK (`attempt_count` >= 0),
  CONSTRAINT `ck_outbox_claim_has_lease` CHECK ((`claim_token` IS NULL) = (`lease_expires_at` IS NULL)),
  CONSTRAINT `ck_outbox_delivered_or_dead` CHECK (NOT (`delivered_at` IS NOT NULL AND `dead_lettered_at` IS NOT NULL))
) STRICT;
