  `subject_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subject_type` CHECK (length(`subject_type`) <= 255),
  `subject_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subject_id` CHECK (length(`subject_id`) <= 36),
  `requested_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `legal_hold` INTEGER NOT NULL DEFAULT 0,
  `status` TEXT COLLATE NOCASE NOT NULL CHECK (status IN('QUEUED','RUNNING','DONE','BLOCKED','FAILED')) CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 255),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `finished_at` INTEGER,
  CONSTRAINT `fk_retention_jobs_179` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_retention_jobs_180` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`)
) STRICT;
CREATE TABLE `countries` (
  `code` TEXT COLLATE BINARY PRIMARY KEY NOT NULL CONSTRAINT `ck_len_code` CHECK (length(`code`) <= 3),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 191),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 32),
  `active` INTEGER NOT NULL DEFAULT 1,
  CONSTRAINT `ck_countries_code` CHECK (`code` GLOB '[A-Z][A-Z][A-Z]'),
  CONSTRAINT `ck_countries_kind` CHECK (`kind` IN ('ISO3166_1', 'FOOTBALL_NATION'))
) STRICT;
CREATE TABLE `canonical_id_sequences` (
  `country_code` TEXT COLLATE BINARY NOT NULL CONSTRAINT `ck_len_country_code` CHECK (length(`country_code`) <= 3),
  `issue_year` INTEGER NOT NULL,
  `last_sequence` INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (`country_code`, `issue_year`),
  CONSTRAINT `fk_seq_country` FOREIGN KEY (`country_code`) REFERENCES `countries` (`code`),
  CONSTRAINT `ck_seq_range` CHECK (`last_sequence` <= 999999),
  CONSTRAINT `ck_seq_year` CHECK (`issue_year` BETWEEN 2000 AND 9999)
) STRICT;
CREATE TABLE `canonical_id_issuances` (
  `canonical_otsi_id` TEXT COLLATE BINARY PRIMARY KEY NOT NULL CONSTRAINT `ck_len_canonical_otsi_id` CHECK (length(`canonical_otsi_id`) <= 20),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `country_code` TEXT COLLATE BINARY NOT NULL CONSTRAINT `ck_len_country_code` CHECK (length(`country_code`) <= 3),
  `issue_year` INTEGER NOT NULL,
  `sequence_number` INTEGER NOT NULL,
  `issuing_organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_issuing_organization_id` CHECK (length(`issuing_organization_id`) <= 36),
  `issued_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_issued_by` CHECK (length(`issued_by`) <= 36),
  `request_key` TEXT COLLATE NOCASE CONSTRAINT `ck_len_request_key` CHECK (length(`request_key`) <= 191),
  `issued_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_issuance_player` UNIQUE (`player_id`),
  CONSTRAINT `uq_issuance_namespace` UNIQUE (`country_code`, `issue_year`, `sequence_number`),
  CONSTRAINT `uq_issuance_request` UNIQUE (`request_key`),
  CONSTRAINT `fk_issuance_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_issuance_country` FOREIGN KEY (`country_code`) REFERENCES `countries` (`code`),
  CONSTRAINT `fk_issuance_org` FOREIGN KEY (`issuing_organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_issuance_user` FOREIGN KEY (`issued_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_issuance_format` CHECK (`canonical_otsi_id` GLOB 'OTSI-[A-Z][A-Z][A-Z]-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9][0-9][0-9]'),
  CONSTRAINT `ck_issuance_parts` CHECK (`canonical_otsi_id` = ('OTSI-' || `country_code` || '-' || printf('%04d', `issue_year`) || '-' || printf('%06d', `sequence_number`))),
  CONSTRAINT `ck_issuance_sequence` CHECK (`sequence_number` BETWEEN 1 AND 999999)
) STRICT;
CREATE TABLE `player_merges` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `from_player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_from_player_id` CHECK (length(`from_player_id`) <= 36),
  `into_player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_into_player_id` CHECK (length(`into_player_id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `decided_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `reason` TEXT COLLATE NOCASE NOT NULL,
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  `decided_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_merge_from` UNIQUE (`from_player_id`),
  CONSTRAINT `fk_merge_from` FOREIGN KEY (`from_player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_merge_into` FOREIGN KEY (`into_player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_merge_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_merge_user` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_merge_evidence` FOREIGN KEY (`evidence_id`) REFERENCES `evidence_records` (`id`),
  CONSTRAINT `ck_merge_distinct` CHECK (`from_player_id` <> `into_player_id`)
) STRICT;
CREATE TABLE `player_external_ids` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `source` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_source` CHECK (length(`source`) <= 64),
  `external_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_external_id` CHECK (length(`external_id`) <= 191),
  `recorded_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_recorded_by` CHECK (length(`recorded_by`) <= 36),
  `recorded_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_external_id` UNIQUE (`source`, `external_id`),
  CONSTRAINT `fk_extid_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_extid_user` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`)
) STRICT;
CREATE TABLE `player_aliases` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `alias` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_alias` CHECK (length(`alias`) <= 255),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 32),
  `source` TEXT COLLATE NOCASE CONSTRAINT `ck_len_source` CHECK (length(`source`) <= 64),
  `recorded_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_player_alias` UNIQUE (`player_id`, `alias`),
  CONSTRAINT `fk_alias_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `ck_alias_kind` CHECK (`kind` IN ('NAME_VARIANT', 'TRANSLITERATION', 'FORMER_NAME', 'NICKNAME'))
) STRICT;
CREATE TABLE `player_nationalities` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `country_code` TEXT COLLATE BINARY NOT NULL CONSTRAINT `ck_len_country_code` CHECK (length(`country_code`) <= 3),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 16),
  `valid_from` INTEGER,
  `valid_to` INTEGER,
  `recorded_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_nat_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_nat_country` FOREIGN KEY (`country_code`) REFERENCES `countries` (`code`),
  CONSTRAINT `ck_nat_kind` CHECK (`kind` IN ('CITIZENSHIP', 'SPORTING')),
  CONSTRAINT `ck_nat_dates` CHECK (`valid_to` IS NULL OR `valid_from` IS NULL OR `valid_to` >= `valid_from`)
) STRICT;
CREATE TABLE `player_club_memberships` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `club_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_club_id` CHECK (length(`club_id`) <= 36),
  `valid_from` INTEGER NOT NULL,
  `valid_to` INTEGER,
  `source` TEXT COLLATE NOCASE CONSTRAINT `ck_len_source` CHECK (length(`source`) <= 64),
  `recorded_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_recorded_by` CHECK (length(`recorded_by`) <= 36),
  `recorded_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_membership_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_membership_club` FOREIGN KEY (`club_id`) REFERENCES `clubs` (`id`),
  CONSTRAINT `fk_membership_user` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_membership_dates` CHECK (`valid_to` IS NULL OR `valid_to` >= `valid_from`)
) STRICT;
CREATE TABLE `player_jersey_numbers` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `club_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_club_id` CHECK (length(`club_id`) <= 36),
  `jersey_number` INTEGER NOT NULL,
  `valid_from` INTEGER NOT NULL,
  `valid_to` INTEGER,
  `source` TEXT COLLATE NOCASE CONSTRAINT `ck_len_source` CHECK (length(`source`) <= 64),
  `recorded_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_jersey_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_jersey_club` FOREIGN KEY (`club_id`) REFERENCES `clubs` (`id`),
  CONSTRAINT `ck_jersey_range` CHECK (`jersey_number` BETWEEN 0 AND 99),
  CONSTRAINT `ck_jersey_dates` CHECK (`valid_to` IS NULL OR `valid_to` >= `valid_from`)
) STRICT;
CREATE TABLE `player_duplicate_candidates` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `player_a_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_a_id` CHECK (length(`player_a_id`) <= 36),
  `player_b_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_b_id` CHECK (length(`player_b_id`) <= 36),
  `score` REAL NOT NULL,
  `basis` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_basis` CHECK (json_valid(`basis`)),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'OPEN' CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 24),
  `reviewed_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_reviewed_by` CHECK (length(`reviewed_by`) <= 36),
  `reviewed_at` INTEGER,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_duplicate_pair` UNIQUE (`player_a_id`, `player_b_id`),
  CONSTRAINT `fk_dup_a` FOREIGN KEY (`player_a_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_dup_b` FOREIGN KEY (`player_b_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_dup_reviewer` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_dup_order` CHECK (`player_a_id` < `player_b_id`),
  CONSTRAINT `ck_dup_score` CHECK (`score` BETWEEN 0 AND 1),
  CONSTRAINT `ck_dup_status` CHECK (`status` IN ('OPEN', 'CONFIRMED_DUPLICATE', 'NOT_DUPLICATE')),
  CONSTRAINT `ck_dup_review` CHECK (`status` = 'OPEN' OR `reviewed_by` IS NOT NULL)
) STRICT;
CREATE TABLE `event_consumer_receipts` (
  `outbox_event_id` INTEGER NOT NULL,
  `subscriber` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subscriber` CHECK (length(`subscriber`) <= 100),
  `completed_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  PRIMARY KEY (`outbox_event_id`, `subscriber`),
  CONSTRAINT `fk_receipt_event` FOREIGN KEY (`outbox_event_id`) REFERENCES `outbox_events` (`id`),
  CONSTRAINT `ck_receipt_subscriber` CHECK ((`subscriber` GLOB '[a-z]*' AND `subscriber` NOT GLOB '*[^a-z0-9_.-]*'))
) STRICT;
CREATE TABLE `local_credentials` (
  `user_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `email_normalized` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_email_normalized` CHECK (length(`email_normalized`) <= 255),
  `password_hash` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_password_hash` CHECK (length(`password_hash`) <= 255),
  `failed_attempts` INTEGER NOT NULL DEFAULT 0,
  `locked_until` INTEGER,
  `password_changed_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_local_credentials_email` UNIQUE (`email_normalized`),
  CONSTRAINT `fk_local_credentials_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_local_credentials_hash` CHECK (`password_hash` LIKE 'scrypt$%'),
  CONSTRAINT `ck_local_credentials_attempts` CHECK (`failed_attempts` >= 0),
  CONSTRAINT `ck_local_credentials_email` CHECK (
    CAST(`email_normalized` AS BLOB) = CAST(lower(`email_normalized`) AS BLOB) AND `email_normalized` LIKE '%_@_%')
) STRICT;
CREATE TABLE `auth_sessions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `family_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_family_id` CHECK (length(`family_id`) <= 36),
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `refresh_hash` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_refresh_hash` CHECK (length(`refresh_hash`) <= 64),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `expires_at` INTEGER NOT NULL,
  `rotated_at` INTEGER,
  `revoked_at` INTEGER,
  `revoke_reason` TEXT COLLATE NOCASE CONSTRAINT `ck_len_revoke_reason` CHECK (length(`revoke_reason`) <= 32),
  `user_agent` TEXT COLLATE NOCASE CONSTRAINT `ck_len_user_agent` CHECK (length(`user_agent`) <= 255),
  `ip` TEXT COLLATE NOCASE CONSTRAINT `ck_len_ip` CHECK (length(`ip`) <= 64),
  CONSTRAINT `uq_auth_sessions_refresh` UNIQUE (`refresh_hash`),
  CONSTRAINT `fk_auth_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_auth_sessions_expiry` CHECK (`expires_at` > `created_at`),
  CONSTRAINT `ck_auth_sessions_reason` CHECK (`revoke_reason` IS NULL OR `revoke_reason` IN ('LOGOUT', 'REUSE_DETECTED', 'PASSWORD_CHANGED', 'ADMIN')),
  CONSTRAINT `ck_auth_sessions_revoked_has_reason` CHECK ((`revoked_at` IS NULL) = (`revoke_reason` IS NULL))
) STRICT;
CREATE TABLE `worker_jobs` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 40),
  `subject_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subject_type` CHECK (length(`subject_type`) <= 40),
  `subject_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subject_id` CHECK (length(`subject_id`) <= 36),
  `dedupe_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_dedupe_key` CHECK (length(`dedupe_key`) <= 191),
  `payload` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_payload` CHECK (json_valid(`payload`)),
  `state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 16),
  `attempts` INTEGER NOT NULL DEFAULT 0,
  `max_attempts` INTEGER NOT NULL DEFAULT 3,
  `available_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `claim_token` TEXT COLLATE NOCASE CONSTRAINT `ck_len_claim_token` CHECK (length(`claim_token`) <= 36),
  `lease_expires_at` INTEGER,
  `heartbeat_at` INTEGER,
  `worker_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_worker_id` CHECK (length(`worker_id`) <= 100),
  `progress` REAL NOT NULL DEFAULT 0,
  `stage_message` TEXT COLLATE NOCASE CONSTRAINT `ck_len_stage_message` CHECK (length(`stage_message`) <= 255),
  `error_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_error_code` CHECK (length(`error_code`) <= 64),
  `error_detail` TEXT COLLATE NOCASE CONSTRAINT `ck_len_error_detail` CHECK (length(`error_detail`) <= 1000),
  `result` TEXT COLLATE NOCASE CONSTRAINT `ck_json_result` CHECK (json_valid(`result`)),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `started_at` INTEGER,
  `finished_at` INTEGER,
  `priority` INTEGER NOT NULL DEFAULT 5,
  `paused_at` INTEGER,
  `paused_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_paused_by` CHECK (length(`paused_by`) <= 36),
  CONSTRAINT `uq_worker_jobs_dedupe` UNIQUE (`dedupe_key`),
  CONSTRAINT `fk_worker_jobs_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `ck_worker_jobs_attempts` CHECK (`attempts` >= 0 AND `max_attempts` >= 1),
  CONSTRAINT `ck_worker_jobs_progress` CHECK (`progress` BETWEEN 0 AND 100),
  CONSTRAINT `ck_worker_jobs_claim_has_lease` CHECK ((`claim_token` IS NULL) = (`lease_expires_at` IS NULL)),
  CONSTRAINT `ck_worker_jobs_running_is_claimed` CHECK ((`state` = 'RUNNING') = (`claim_token` IS NOT NULL)),
  CONSTRAINT `ck_worker_jobs_failed_has_error` CHECK (`state` <> 'FAILED' OR `error_code` IS NOT NULL),
  CONSTRAINT `ck_worker_jobs_state` CHECK (`state` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'PAUSED')),
  CONSTRAINT `ck_worker_jobs_priority` CHECK (`priority` BETWEEN 1 AND 9),
  CONSTRAINT `ck_worker_jobs_paused_pair` CHECK ((`state` <> 'PAUSED' OR `paused_at` IS NOT NULL) AND (`paused_at` IS NULL) = (`paused_by` IS NULL)),
  CONSTRAINT `ck_worker_jobs_kind` CHECK (`kind` IN ('INGEST_UPLOAD', 'INGEST_URL', 'PROXY', 'ANALYZE', 'RENDER', 'ASSESS', 'CALIBRATE_PITCH', 'TRACK_BALL', 'READ_LINEUPS', 'SNAPSHOT', 'BEAT_GRID'))
) STRICT;
CREATE TABLE `track_appearance` (
  `track_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `kit_group` INTEGER,
  `kit_rgb` TEXT COLLATE NOCASE CONSTRAINT `ck_len_kit_rgb` CHECK (length(`kit_rgb`) <= 7),
  `embedding_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_embedding_asset_id` CHECK (length(`embedding_asset_id`) <= 36),
  `embedding_row` INTEGER,
  `crop_count` INTEGER NOT NULL DEFAULT 0,
  `drift_score` REAL,
  `thumbnail_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_thumbnail_asset_id` CHECK (length(`thumbnail_asset_id`) <= 36),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_track_appearance_track` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_track_appearance_run` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_track_appearance_emb` FOREIGN KEY (`embedding_asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_track_appearance_thumb` FOREIGN KEY (`thumbnail_asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_track_appearance_model` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
  CONSTRAINT `ck_track_appearance` CHECK ((`kit_group` IS NULL OR `kit_group` BETWEEN 0 AND 9) AND `crop_count` >= 0
    AND (`drift_score` IS NULL OR `drift_score` BETWEEN -1 AND 1) AND (`kit_rgb` IS NULL OR `kit_rgb` GLOB '#[0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F]')
    AND ((`embedding_asset_id` IS NULL) = (`embedding_row` IS NULL)))
) STRICT;
CREATE TABLE `track_links` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `track_a_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_a_id` CHECK (length(`track_a_id`) <= 36),
  `track_b_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_b_id` CHECK (length(`track_b_id`) <= 36),
  `score` REAL NOT NULL,
  `method` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_method` CHECK (length(`method`) <= 32),
  `crosses_cut` INTEGER NOT NULL,
  `gap_us` INTEGER NOT NULL,
  `evidence` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_evidence` CHECK (json_valid(`evidence`)),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_track_links_pair` UNIQUE (`track_a_id`, `track_b_id`),
  CONSTRAINT `fk_track_links_run` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_track_links_a` FOREIGN KEY (`track_a_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_track_links_b` FOREIGN KEY (`track_b_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_track_links_model` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
  CONSTRAINT `ck_track_links` CHECK (`track_a_id` <> `track_b_id` AND `score` BETWEEN 0 AND 1 AND `gap_us` >= 0 AND `method` IN ('APPEARANCE'))
) STRICT;
CREATE TABLE `track_link_decisions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `link_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_link_id` CHECK (length(`link_id`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_state` CHECK (`state` IN ('CONFIRMED', 'REJECTED', 'UNRESOLVED')),
  `decided_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `reason` TEXT COLLATE NOCASE,
  `supersedes_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_supersedes_id` CHECK (length(`supersedes_id`) <= 36),
  `decided_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_link_decisions_supersedes` UNIQUE (`supersedes_id`),
  CONSTRAINT `fk_link_decisions_link` FOREIGN KEY (`link_id`) REFERENCES `track_links` (`id`),
  CONSTRAINT `fk_link_decisions_user` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_link_decisions_supersedes` FOREIGN KEY (`supersedes_id`) REFERENCES `track_link_decisions` (`id`)
) STRICT;
CREATE TABLE `match_roster_changes` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `match_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_match_id` CHECK (length(`match_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `action` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_action` CHECK (length(`action`) <= 16),
  `before_state` TEXT COLLATE NOCASE CONSTRAINT `ck_json_before_state` CHECK (json_valid(`before_state`)),
  `after_state` TEXT COLLATE NOCASE CONSTRAINT `ck_json_after_state` CHECK (json_valid(`after_state`)),
  `changed_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_changed_by` CHECK (length(`changed_by`) <= 36),
  `reason` TEXT COLLATE NOCASE,
  `changed_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_roster_changes_match` FOREIGN KEY (`match_id`) REFERENCES `matches` (`id`),
  CONSTRAINT `fk_roster_changes_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_roster_changes_user` FOREIGN KEY (`changed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_roster_changes_action` CHECK (`action` IN ('ADDED', 'UPDATED', 'REMOVED', 'VERIFIED', 'UNVERIFIED'))
) STRICT;
CREATE TABLE `run_team_assignments` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `kit_group` INTEGER NOT NULL,
  `club_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_club_id` CHECK (length(`club_id`) <= 36),
  `decided_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `reason` TEXT COLLATE NOCASE,
  `supersedes_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_supersedes_id` CHECK (length(`supersedes_id`) <= 36),
  `decided_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_team_assign_supersedes` UNIQUE (`supersedes_id`),
  CONSTRAINT `fk_team_assign_run` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_team_assign_club` FOREIGN KEY (`club_id`) REFERENCES `clubs` (`id`),
  CONSTRAINT `fk_team_assign_user` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_team_assign_supersedes` FOREIGN KEY (`supersedes_id`) REFERENCES `run_team_assignments` (`id`),
  CONSTRAINT `ck_team_assign_group` CHECK (`kit_group` BETWEEN 0 AND 9)
) STRICT;
CREATE TABLE `track_jersey_evidence` (
  `track_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 12),
  `number` TEXT COLLATE NOCASE CONSTRAINT `ck_len_number` CHECK (length(`number`) <= 2),
  `confidence` REAL,
  `side` TEXT COLLATE NOCASE NOT NULL DEFAULT 'UNKNOWN' CONSTRAINT `ck_len_side` CHECK (length(`side`) <= 8),
  `candidate_frames` INTEGER NOT NULL DEFAULT 0,
  `frame_reads` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_array()) CONSTRAINT `ck_json_frame_reads` CHECK (json_valid(`frame_reads`)),
  `alternatives` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_array()) CONSTRAINT `ck_json_alternatives` CHECK (json_valid(`alternatives`)),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_jersey_evidence_track` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_jersey_evidence_run` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_jersey_evidence_model` FOREIGN KEY (`model_version_id`) REFERENCES `model_versions` (`id`),
  CONSTRAINT `ck_jersey_evidence` CHECK (`state` IN ('RECOGNIZED', 'UNCERTAIN', 'UNREADABLE', 'TOO_SMALL') AND `side` IN ('BACK', 'FRONT', 'UNKNOWN')
    AND (`number` IS NULL OR (`number` GLOB '[0-9]' OR `number` GLOB '[0-9][0-9]')) AND (`state` NOT IN ('RECOGNIZED', 'UNCERTAIN') OR `number` IS NOT NULL)
    AND `candidate_frames` >= 0 AND (`confidence` IS NULL OR `confidence` BETWEEN 0 AND 1))
) STRICT;
CREATE TABLE `jersey_number_decisions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `number` TEXT COLLATE NOCASE CONSTRAINT `ck_len_number` CHECK (length(`number`) <= 2),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 12),
  `decided_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `reason` TEXT COLLATE NOCASE,
  `supersedes_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_supersedes_id` CHECK (length(`supersedes_id`) <= 36),
  `decided_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_jersey_decisions_supersedes` UNIQUE (`supersedes_id`),
  CONSTRAINT `fk_jersey_decisions_track` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_jersey_decisions_user` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_jersey_decisions_supersedes` FOREIGN KEY (`supersedes_id`) REFERENCES `jersey_number_decisions` (`id`),
  CONSTRAINT `ck_jersey_decisions` CHECK (`state` IN ('CONFIRMED', 'UNREADABLE') AND (`number` IS NULL OR (`number` GLOB '[0-9]' OR `number` GLOB '[0-9][0-9]'))
    AND (`state` <> 'CONFIRMED' OR `number` IS NOT NULL))
) STRICT;
CREATE TABLE `track_neighbours` (
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `neighbour_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_neighbour_id` CHECK (length(`neighbour_id`) <= 36),
  `cosine` REAL NOT NULL,
  `kit_similarity` REAL NOT NULL,
  `rank_no` INTEGER NOT NULL,
  PRIMARY KEY (`track_id`, `neighbour_id`),
  CONSTRAINT `fk_track_neighbours_track` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `fk_track_neighbours_other` FOREIGN KEY (`neighbour_id`) REFERENCES `tracks` (`id`),
  CONSTRAINT `ck_track_neighbours` CHECK (`track_id` <> `neighbour_id` AND `cosine` BETWEEN -1 AND 1 AND `kit_similarity` BETWEEN 0 AND 1 AND `rank_no` BETWEEN 1 AND 20)
) STRICT;
CREATE TABLE `video_quality_assessments` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 12),
  `metrics` TEXT COLLATE NOCASE CONSTRAINT `ck_json_metrics` CHECK (json_valid(`metrics`)),
  `recommended_profile` TEXT COLLATE NOCASE CONSTRAINT `ck_len_recommended_profile` CHECK (length(`recommended_profile`) <= 24),
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 64),
  `failure_detail` TEXT COLLATE NOCASE,
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `finished_at` INTEGER,
  CONSTRAINT `fk_quality_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_quality_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_quality_user` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_quality_status` CHECK (`status` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED')
    AND (`recommended_profile` IS NULL OR `recommended_profile` IN ('STANDARD', 'HIGH_ACCURACY', 'ULTRA_SENSITIVE'))
    AND (`status` <> 'SUCCEEDED' OR (`metrics` IS NOT NULL AND `recommended_profile` IS NOT NULL)))
) STRICT;
CREATE TABLE `worker_status` (
  `worker_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_worker_id` CHECK (length(`worker_id`) <= 100),
  `host` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_host` CHECK (length(`host`) <= 255),
  `kinds` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_kinds` CHECK (json_valid(`kinds`)),
  `cpu_percent` REAL CHECK (`cpu_percent` BETWEEN 0 AND 100),
  `cpu_count` INTEGER CHECK (`cpu_count` > 0),
  `memory_used_bytes` INTEGER CHECK (`memory_used_bytes` >= 0),
  `memory_total_bytes` INTEGER CHECK (`memory_total_bytes` > 0),
  `gpu_name` TEXT COLLATE NOCASE CONSTRAINT `ck_len_gpu_name` CHECK (length(`gpu_name`) <= 255),
  `gpu_percent` REAL CHECK (`gpu_percent` BETWEEN 0 AND 100),
  `busy` INTEGER NOT NULL DEFAULT 0,
  `started_at` INTEGER NOT NULL,
  `reported_at` INTEGER NOT NULL
) STRICT;
CREATE TABLE `video_ingest_options` (
  `video_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `stabilize_video` INTEGER NOT NULL,
  `auto_crop_pitch` INTEGER NOT NULL DEFAULT 0,
  `enhance_quality` INTEGER NOT NULL DEFAULT 0,
  `remove_crowd_noise` INTEGER NOT NULL DEFAULT 0,
  `correct_aspect_ratio` INTEGER NOT NULL DEFAULT 0,
  `overlay_players_teams` INTEGER NOT NULL DEFAULT 1,
  `overlay_ball_tracking` INTEGER NOT NULL DEFAULT 1,
  `overlay_jersey_numbers` INTEGER NOT NULL DEFAULT 1,
  `overlay_pitch_lines` INTEGER NOT NULL DEFAULT 0,
  `overlay_event_markers` INTEGER NOT NULL DEFAULT 0,
  `auto_create_match` INTEGER NOT NULL DEFAULT 0,
  `extract_metadata` INTEGER NOT NULL DEFAULT 1,
  `generate_highlights` INTEGER NOT NULL DEFAULT 0,
  `send_to_analysis` INTEGER NOT NULL,
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `auto_outcome` TEXT COLLATE NOCASE CONSTRAINT `ck_len_auto_outcome` CHECK (length(`auto_outcome`) <= 12),
  `auto_run_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_auto_run_id` CHECK (length(`auto_run_id`) <= 36),
  `auto_detail` TEXT COLLATE NOCASE CONSTRAINT `ck_len_auto_detail` CHECK (length(`auto_detail`) <= 255),
  `auto_decided_at` INTEGER,
  `analysis_profile` TEXT COLLATE NOCASE CONSTRAINT `ck_len_analysis_profile` CHECK (length(`analysis_profile`) <= 16),
  `auto_profile` TEXT COLLATE NOCASE CONSTRAINT `ck_len_auto_profile` CHECK (length(`auto_profile`) <= 16),
  CONSTRAINT `fk_ingest_options_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_ingest_options_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_ingest_options_outcome` CHECK (`auto_outcome` IS NULL OR `auto_outcome` IN ('STARTED', 'SKIPPED')),
  CONSTRAINT `ck_ingest_options_decided` CHECK ((`auto_outcome` IS NULL) = (`auto_decided_at` IS NULL)),
  CONSTRAINT `ck_ingest_options_started_has_run` CHECK (`auto_outcome` <> 'STARTED' OR `auto_run_id` IS NOT NULL),
  CONSTRAINT `ck_ingest_options_profile` CHECK (`analysis_profile` IS NULL OR `analysis_profile` IN ('RECOMMENDED', 'STANDARD', 'HIGH_ACCURACY', 'ULTRA_SENSITIVE')),
  CONSTRAINT `ck_ingest_options_auto_profile` CHECK (`auto_profile` IS NULL OR `auto_profile` IN ('STANDARD', 'HIGH_ACCURACY', 'ULTRA_SENSITIVE'))
) STRICT;
CREATE TABLE `user_avatars` (
  `user_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `mime` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_mime` CHECK (length(`mime`) <= 32),
  `image` BLOB NOT NULL,
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_avatar_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_avatar_mime` CHECK (`mime` IN ('image/jpeg','image/png','image/webp')),
  CONSTRAINT `ck_avatar_size` CHECK (length(CAST(`image` AS BLOB)) <= 409600)
) STRICT;
CREATE TABLE `pitch_calibration_requests` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `anchor_pts_us` INTEGER NOT NULL,
  `points` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_points` CHECK (json_valid(`points`)),
  `pitch_length_m` REAL NOT NULL,
  `pitch_width_m` REAL NOT NULL,
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 12),
  `metrics` TEXT COLLATE NOCASE CONSTRAINT `ck_json_metrics` CHECK (json_valid(`metrics`)),
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 64),
  `failure_detail` TEXT COLLATE NOCASE,
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `finished_at` INTEGER,
  `mode` TEXT COLLATE NOCASE NOT NULL DEFAULT 'CLICKS' CONSTRAINT `ck_len_mode` CHECK (length(`mode`) <= 8),
  CONSTRAINT `fk_pcr_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_pcr_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_pcr_user` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_pcr_pitch` CHECK (`pitch_length_m` BETWEEN 90 AND 120 AND `pitch_width_m` BETWEEN 45 AND 90 AND `anchor_pts_us` >= 0),
  CONSTRAINT `ck_pcr_status` CHECK (`status` IN ('QUEUED', 'RUNNING', 'WAITING', 'SUCCEEDED', 'FAILED')),
  CONSTRAINT `ck_pcr_mode` CHECK (`mode` IN ('CLICKS', 'AUTO'))
) STRICT;
CREATE TABLE `pitch_cameras` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `centre_x_m` REAL NOT NULL,
  `centre_y_m` REAL NOT NULL,
  `height_m` REAL NOT NULL,
  `roll_deg` REAL NOT NULL,
  `pitch_length_m` REAL NOT NULL,
  `pitch_width_m` REAL NOT NULL,
  `moments` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_moments` CHECK (json_valid(`moments`)),
  `points` INTEGER NOT NULL,
  `click_rms_px` REAL NOT NULL,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_pcam_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_pcam_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `ck_pcam_values` CHECK (`height_m` > 0 AND `points` >= 2 AND `click_rms_px` >= 0 AND `pitch_length_m` BETWEEN 90 AND 120 AND `pitch_width_m` BETWEEN 45 AND 90)
) STRICT;
CREATE TABLE `ball_marks` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `pts_us` INTEGER NOT NULL,
  `visible` INTEGER NOT NULL,
  `x` REAL,
  `y` REAL,
  `marked_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_marked_by` CHECK (length(`marked_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`video_id`, `pts_us`),
  CONSTRAINT `fk_bm_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_bm_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_bm_user` FOREIGN KEY (`marked_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_bm_position` CHECK ((`visible` AND `x` BETWEEN 0 AND 1 AND `y` BETWEEN 0 AND 1) OR (NOT `visible` AND `x` IS NULL AND `y` IS NULL)),
  CONSTRAINT `ck_bm_time` CHECK (`pts_us` >= 0)
) STRICT;
CREATE TABLE `ball_tracks` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 12),
  `metrics` TEXT COLLATE NOCASE CONSTRAINT `ck_json_metrics` CHECK (json_valid(`metrics`)),
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 64),
  `failure_detail` TEXT COLLATE NOCASE,
  `requested_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `finished_at` INTEGER,
  CONSTRAINT `fk_bt_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_bt_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_bt_run` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_bt_user` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_bt_status` CHECK (`status` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED'))
) STRICT;
CREATE TABLE `ball_positions` (
  `ball_track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_ball_track_id` CHECK (length(`ball_track_id`) <= 36),
  `pts_us` INTEGER NOT NULL,
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 10),
  `x` REAL NOT NULL,
  `y` REAL NOT NULL,
  `confidence` REAL NOT NULL,
  PRIMARY KEY (`ball_track_id`, `pts_us`),
  CONSTRAINT `fk_bp_track` FOREIGN KEY (`ball_track_id`) REFERENCES `ball_tracks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_bp_state` CHECK (`state` IN ('DETECTED', 'INFERRED')),
  CONSTRAINT `ck_bp_values` CHECK (`pts_us` >= 0 AND `x` BETWEEN 0 AND 1 AND `y` BETWEEN 0 AND 1 AND `confidence` BETWEEN 0 AND 1)
) STRICT;
CREATE TABLE `lineup_reads` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 12),
  `metrics` TEXT COLLATE NOCASE CONSTRAINT `ck_json_metrics` CHECK (json_valid(`metrics`)),
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 64),
  `failure_detail` TEXT COLLATE NOCASE,
  `requested_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `finished_at` INTEGER,
  CONSTRAINT `fk_lr_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_lr_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_lr_user` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_lr_status` CHECK (`status` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED'))
) STRICT;
CREATE TABLE `lineup_cards` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `read_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_read_id` CHECK (length(`read_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `pts_us` INTEGER NOT NULL,
  `team_name` TEXT COLLATE NOCASE CONSTRAINT `ck_len_team_name` CHECK (length(`team_name`) <= 255),
  `coach_name` TEXT COLLATE NOCASE CONSTRAINT `ck_len_coach_name` CHECK (length(`coach_name`) <= 255),
  `entries` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_entries` CHECK (json_valid(`entries`)),
  `frame_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_frame_asset_id` CHECK (length(`frame_asset_id`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'PROPOSED' CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 10),
  `applied_match_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_applied_match_id` CHECK (length(`applied_match_id`) <= 36),
  `applied_club_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_applied_club_id` CHECK (length(`applied_club_id`) <= 36),
  `decided_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `decided_at` INTEGER,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_lc_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_lc_read` FOREIGN KEY (`read_id`) REFERENCES `lineup_reads` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_lc_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_lc_asset` FOREIGN KEY (`frame_asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_lc_match` FOREIGN KEY (`applied_match_id`) REFERENCES `matches` (`id`),
  CONSTRAINT `fk_lc_club` FOREIGN KEY (`applied_club_id`) REFERENCES `clubs` (`id`),
  CONSTRAINT `fk_lc_user` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_lc_state` CHECK (`state` IN ('PROPOSED', 'APPLIED', 'DISMISSED')),
  CONSTRAINT `ck_lc_applied` CHECK (`state` <> 'APPLIED' OR (`applied_match_id` IS NOT NULL AND `applied_club_id` IS NOT NULL AND `decided_by` IS NOT NULL)),
  CONSTRAINT `ck_lc_pts` CHECK (`pts_us` >= 0)
) STRICT;
CREATE TABLE `match_periods` (
  `video_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `run_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 10),
  `first_start_us` INTEGER NOT NULL,
  `first_end_us` INTEGER NOT NULL,
  `second_start_us` INTEGER,
  `second_end_us` INTEGER,
  `note` TEXT COLLATE NOCASE,
  `per_minute` TEXT COLLATE NOCASE CONSTRAINT `ck_json_per_minute` CHECK (json_valid(`per_minute`)),
  `decided_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `decided_at` INTEGER,
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_mp_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_mp_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`),
  CONSTRAINT `fk_mp_run` FOREIGN KEY (`run_id`) REFERENCES `pipeline_runs` (`id`),
  CONSTRAINT `fk_mp_user` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_mp_state` CHECK (`state` IN ('PROPOSED', 'CONFIRMED')),
  CONSTRAINT `ck_mp_first` CHECK (`first_start_us` >= 0 AND `first_end_us` > `first_start_us`),
  CONSTRAINT `ck_mp_second` CHECK ((`second_start_us` IS NULL AND `second_end_us` IS NULL)
    OR (`second_start_us` >= `first_end_us` AND `second_end_us` > `second_start_us`)),
  CONSTRAINT `ck_mp_decided` CHECK (`state` <> 'CONFIRMED' OR (`decided_by` IS NOT NULL AND `decided_at` IS NOT NULL))
) STRICT;
CREATE TABLE `brand_assets` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 20),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 120),
  `asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_asset_id` CHECK (length(`asset_id`) <= 36),
  `rights_grant_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_rights_grant_id` CHECK (length(`rights_grant_id`) <= 36),
  `rights_holder` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_rights_holder` CHECK (length(`rights_holder`) <= 255),
  `rights_basis` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_rights_basis` CHECK (length(`rights_basis`) <= 20),
  `uploaded_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_uploaded_by` CHECK (length(`uploaded_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `retired_at` INTEGER,
  CONSTRAINT `fk_ba_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_ba_asset` FOREIGN KEY (`asset_id`, `organization_id`) REFERENCES `assets` (`id`, `organization_id`),
  CONSTRAINT `fk_ba_grant` FOREIGN KEY (`rights_grant_id`) REFERENCES `rights_grants` (`id`),
  CONSTRAINT `fk_ba_user` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_ba_basis` CHECK (`rights_basis` IN ('OWN_BRAND', 'LICENSED', 'PERMISSION', 'FREE_LICENCE')),
  CONSTRAINT `ck_ba_kind` CHECK (`kind` IN ('COMPETITION_LOGO', 'CUSTOM_LOGO', 'MUSIC', 'REEL_VIDEO'))
) STRICT;
CREATE TABLE `organization_invitations` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `email_normalized` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_email_normalized` CHECK (length(`email_normalized`) <= 255),
  `role` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_role` CHECK (length(`role`) <= 16),
  `token_hash` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_token_hash` CHECK (length(`token_hash`) <= 64),
  `invited_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_invited_by` CHECK (length(`invited_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `expires_at` INTEGER NOT NULL,
  `accepted_at` INTEGER,
  `accepted_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_accepted_by` CHECK (length(`accepted_by`) <= 36),
  `revoked_at` INTEGER,
  `open_email` TEXT COLLATE NOCASE GENERATED ALWAYS AS ((CASE WHEN `accepted_at` IS NULL AND `revoked_at` IS NULL THEN `email_normalized` ELSE NULL END)) STORED CONSTRAINT `ck_len_open_email` CHECK (length(`open_email`) <= 255),
  CONSTRAINT `uq_invitations_token` UNIQUE (`token_hash`),
  CONSTRAINT `uq_invitations_open` UNIQUE (`organization_id`, `open_email`),
  CONSTRAINT `fk_invitations_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_invitations_inviter` FOREIGN KEY (`invited_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_invitations_acceptor` FOREIGN KEY (`accepted_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_invitations_role` CHECK (`role` IN ('OWNER', 'ADMIN', 'ANALYST', 'EDITOR', 'SCOUT', 'VIEWER')),
  CONSTRAINT `ck_invitations_email` CHECK (`email_normalized` = lower(`email_normalized`) AND `email_normalized` LIKE '%_@_%'),
  CONSTRAINT `ck_invitations_expiry` CHECK (`expires_at` > `created_at`),
  CONSTRAINT `ck_invitations_used_once` CHECK (`accepted_at` IS NULL OR `revoked_at` IS NULL),
  CONSTRAINT `ck_invitations_acceptor` CHECK ((`accepted_at` IS NULL) = (`accepted_by` IS NULL))
) STRICT;
CREATE TABLE `user_totp` (
  `user_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `secret_sealed` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_secret_sealed` CHECK (length(`secret_sealed`) <= 255),
  `confirmed_at` INTEGER,
  `last_used_step` INTEGER,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_user_totp_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_user_totp_sealed` CHECK (`secret_sealed` LIKE 'v1.%')
) STRICT;
CREATE TABLE `user_recovery_codes` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `code_hash` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_code_hash` CHECK (length(`code_hash`) <= 64),
  `used_at` INTEGER,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `uq_user_recovery_codes_hash` UNIQUE (`user_id`, `code_hash`),
  CONSTRAINT `fk_user_recovery_codes_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) STRICT;
CREATE TABLE `library_folders` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 255),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
