  CONSTRAINT `fk_library_folder_removed_by` FOREIGN KEY (`removed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_library_folder_name` CHECK (length(trim(`name`)) >= 1),
  CONSTRAINT `ck_library_folder_removed_pair` CHECK ((`removed_at` IS NULL) = (`removed_by` IS NULL))
) STRICT;
CREATE TABLE `library_folder_items` (
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `item_kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_item_kind` CHECK (length(`item_kind`) <= 16),
  `item_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_item_id` CHECK (length(`item_id`) <= 36),
  `folder_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_folder_id` CHECK (length(`folder_id`) <= 36),
  `added_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_added_by` CHECK (length(`added_by`) <= 36),
  `added_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  PRIMARY KEY (`organization_id`, `item_kind`, `item_id`),
