  CONSTRAINT `fk_library_item_folder` FOREIGN KEY (`folder_id`) REFERENCES `library_folders` (`id`),
  CONSTRAINT `fk_library_item_added_by` FOREIGN KEY (`added_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_library_item_kind` CHECK (`item_kind` IN ('reel', 'render', 'video', 'match', 'project'))
) STRICT;
CREATE TABLE `library_deletions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `item_kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_item_kind` CHECK (length(`item_kind`) <= 16),
  `item_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_item_id` CHECK (length(`item_id`) <= 36),
  `title` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_title` CHECK (length(`title`) <= 512),
  `deleted_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_deleted_by` CHECK (length(`deleted_by`) <= 36),
  `deleted_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `restored_at` INTEGER,
  `restored_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_restored_by` CHECK (length(`restored_by`) <= 36),
  CONSTRAINT `fk_library_deletion_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_library_deletion_by` FOREIGN KEY (`deleted_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_library_deletion_restored_by` FOREIGN KEY (`restored_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_library_deletion_kind` CHECK (`item_kind` IN ('reel', 'render', 'video', 'match', 'project', 'folder')),
  CONSTRAINT `ck_library_deletion_restored_pair` CHECK ((`restored_at` IS NULL) = (`restored_by` IS NULL))
) STRICT;
CREATE TABLE `library_deletion_items` (
  `deletion_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_deletion_id` CHECK (length(`deletion_id`) <= 36),
  `item_kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_item_kind` CHECK (length(`item_kind`) <= 16),
  `item_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_item_id` CHECK (length(`item_id`) <= 36),
  `prior` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_prior` CHECK (json_valid(`prior`)),
  PRIMARY KEY (`deletion_id`, `item_kind`, `item_id`),
  CONSTRAINT `fk_library_deletion_item` FOREIGN KEY (`deletion_id`) REFERENCES `library_deletions` (`id`),
  CONSTRAINT `ck_library_deletion_item_kind` CHECK (`item_kind` IN ('reel', 'render', 'video', 'match', 'project', 'folder'))
) STRICT;
CREATE TABLE `player_tags` (
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `tag` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_tag` CHECK (length(`tag`) <= 40),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  PRIMARY KEY (`organization_id`, `player_id`, `tag`),
  CONSTRAINT `fk_player_tags_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_player_tags_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_player_tags_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_player_tags_tag` CHECK (length(trim(`tag`)) BETWEEN 1 AND 40)
) STRICT;
CREATE TABLE `player_assessments` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `draft` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_draft` CHECK (json_valid(`draft`)),
  `published` TEXT COLLATE NOCASE CONSTRAINT `ck_json_published` CHECK (json_valid(`published`)),
  `published_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_published_by` CHECK (length(`published_by`) <= 36),
  `published_at` INTEGER,
  `updated_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_updated_by` CHECK (length(`updated_by`) <= 36),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `version` INTEGER NOT NULL DEFAULT 1,
  UNIQUE (`organization_id`, `player_id`),
  CONSTRAINT `fk_player_assessments_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_player_assessments_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_player_assessments_published_by` FOREIGN KEY (`published_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_player_assessments_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_player_assessments_published` CHECK ((`published` IS NULL) = (`published_by` IS NULL) AND (`published` IS NULL) = (`published_at` IS NULL)),
  CONSTRAINT `ck_player_assessments_version` CHECK (`version` >= 1)
) STRICT;
CREATE TABLE `scouting_dossiers` (
