  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 80),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `name`),
  CONSTRAINT `fk_scouting_dossiers_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_scouting_dossiers_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_scouting_dossiers_name` CHECK (length(trim(`name`)) BETWEEN 1 AND 80)
) STRICT;
CREATE TABLE `scouting_dossier_players` (
