  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `added_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_added_by` CHECK (length(`added_by`) <= 36),
  `added_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  PRIMARY KEY (`dossier_id`, `player_id`),
  CONSTRAINT `fk_scouting_dossier_players_dossier` FOREIGN KEY (`dossier_id`) REFERENCES `scouting_dossiers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_scouting_dossier_players_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_scouting_dossier_players_by` FOREIGN KEY (`added_by`) REFERENCES `users` (`id`)
) STRICT;
CREATE TABLE `export_bundles` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `reel_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `render_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_render_id` CHECK (length(`render_id`) <= 36),
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `items` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_items` CHECK (json_valid(`items`)),
  `zip_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_zip_asset_id` CHECK (length(`zip_asset_id`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `completed_at` INTEGER,
  CONSTRAINT `fk_eb_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_eb_reel` FOREIGN KEY (`reel_id`) REFERENCES `reel_projects` (`id`),
  CONSTRAINT `fk_eb_render` FOREIGN KEY (`render_id`) REFERENCES `render_jobs` (`id`),
  CONSTRAINT `fk_eb_by` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_eb_zip` FOREIGN KEY (`zip_asset_id`) REFERENCES `assets` (`id`)
) STRICT;
CREATE TABLE `export_bundle_items` (
  `bundle_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_bundle_id` CHECK (length(`bundle_id`) <= 36),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_kind` CHECK (`kind` IN ('PERFORMANCE_PDF', 'CLIP_SHEET_PDF', 'EVENTS_CSV', 'HEATMAP_PNG')),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_state` CHECK (`state` IN ('SUCCEEDED', 'FAILED', 'NOT_MEASURED')),
  `asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_asset_id` CHECK (length(`asset_id`) <= 36),
  `report_job_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_report_job_id` CHECK (length(`report_job_id`) <= 36),
  `byte_size` INTEGER,
  `sha256` TEXT COLLATE NOCASE CONSTRAINT `ck_len_sha256` CHECK (length(`sha256`) <= 64),
  `failure` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure` CHECK (length(`failure`) <= 255),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  PRIMARY KEY (`bundle_id`, `kind`),
  CONSTRAINT `fk_ebi_bundle` FOREIGN KEY (`bundle_id`) REFERENCES `export_bundles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ebi_asset` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_ebi_report` FOREIGN KEY (`report_job_id`) REFERENCES `report_jobs` (`id`),
  CONSTRAINT `ck_ebi_file` CHECK ((`state` = 'SUCCEEDED') = (`asset_id` IS NOT NULL))
) STRICT;
CREATE TABLE `user_page_modes` (
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `page` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_page` CHECK (length(`page`) <= 16),
  `mode` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_mode` CHECK (length(`mode`) <= 8),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  PRIMARY KEY (`user_id`, `page`),
  CONSTRAINT `fk_page_mode_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_page_mode_mode` CHECK (`mode` IN ('GUIDED', 'PRO')),
  CONSTRAINT `ck_page_mode_page` CHECK (`page` IN ('home', 'upload', 'processing', 'analysis', 'tactical', 'reels', 'studio', 'reports', 'library', 'export'))
) STRICT;
CREATE TABLE `notification_reads` (
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `seen_at` INTEGER NOT NULL,
  PRIMARY KEY (`user_id`, `organization_id`),
  CONSTRAINT `fk_notification_reads_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_notification_reads_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) STRICT;
CREATE TABLE `reel_edits` (
  `id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `reel_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `seq` INTEGER NOT NULL,
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 8),
  `action` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_action` CHECK (length(`action`) <= 64),
  `label` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_label` CHECK (length(`label`) <= 255),
  `state` TEXT COLLATE NOCASE CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 8),
  `target_edit_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_target_edit_id` CHECK (length(`target_edit_id`) <= 36),
  `actor_user_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_actor_user_id` CHECK (length(`actor_user_id`) <= 36),
  `before_state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_before_state` CHECK (json_valid(`before_state`)),
  `after_state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_after_state` CHECK (json_valid(`after_state`)),
  `before_hash` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_before_hash` CHECK (length(`before_hash`) <= 64),
  `after_hash` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_after_hash` CHECK (length(`after_hash`) <= 64),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`reel_id`, `seq`),
  CONSTRAINT `fk_reel_edits_reel` FOREIGN KEY (`reel_id`, `organization_id`) REFERENCES `reel_projects` (`id`, `organization_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_reel_edits_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_reel_edits_actor` FOREIGN KEY (`actor_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_reel_edits_kind` CHECK (`kind` IN ('EDIT', 'UNDO', 'REDO')),
  CONSTRAINT `ck_reel_edits_state` CHECK ((`kind` = 'EDIT') = (`state` IS NOT NULL) AND (`state` IS NULL OR `state` IN ('ACTIVE', 'UNDONE', 'DROPPED'))),
  CONSTRAINT `ck_reel_edits_target` CHECK ((`kind` = 'EDIT') = (`target_edit_id` IS NULL)),
  CONSTRAINT `ck_reel_edits_states_json` CHECK (json_type(`before_state`) = 'object' AND json_type(`after_state`) = 'object')
) STRICT;
CREATE TABLE `video_markers` (
  `id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `at_pts_us` INTEGER NOT NULL,
  `body` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_body` CHECK (length(`body`) <= 500),
  `created_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `removed_at` INTEGER,
  CONSTRAINT `fk_video_markers_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_video_markers_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_video_markers_author` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_video_markers_at` CHECK (`at_pts_us` >= 0)
) STRICT;
CREATE TABLE `snapshots` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `pts_us` INTEGER NOT NULL,
  `frame_pts_us` INTEGER,
  `overlays` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_overlays` CHECK (json_valid(`overlays`)),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 12),
  `asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_asset_id` CHECK (length(`asset_id`) <= 36),
  `width` INTEGER,
  `height` INTEGER,
  `boxes_drawn` INTEGER,
  `run_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 64),
  `failure_detail` TEXT COLLATE NOCASE,
  `requested_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `finished_at` INTEGER,
  `removed_at` INTEGER,
  CONSTRAINT `fk_snap_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_snap_video` FOREIGN KEY (`video_id`, `organization_id`) REFERENCES `video_sources` (`id`, `organization_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_snap_asset` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_snap_user` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_snap_status` CHECK (`status` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED')),
  CONSTRAINT `ck_snap_pts` CHECK (`pts_us` >= 0)
) STRICT;
CREATE TABLE `search_documents` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 12),
  `entity_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_entity_id` CHECK (length(`entity_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `at_us` INTEGER,
  `title` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_title` CHECK (length(`title`) <= 300),
  `detail` TEXT COLLATE NOCASE CONSTRAINT `ck_len_detail` CHECK (length(`detail`) <= 300),
  `ref` TEXT COLLATE NOCASE CONSTRAINT `ck_len_ref` CHECK (length(`ref`) <= 64),
  `event_type` TEXT COLLATE NOCASE CONSTRAINT `ck_len_event_type` CHECK (length(`event_type`) <= 32),
  `analysed` INTEGER,
  `confirmed` INTEGER,
  `sort_at` INTEGER NOT NULL,
  `indexed_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `period` TEXT COLLATE NOCASE CONSTRAINT `ck_len_period` CHECK (length(`period`) <= 8),
  UNIQUE (`organization_id`, `kind`, `entity_id`),
  CONSTRAINT `fk_search_doc_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_search_doc_kind` CHECK (`kind` IN ('MATCH', 'PLAYER', 'REEL', 'PROJECT', 'MOMENT', 'MARKER'))
) STRICT;
CREATE TABLE `search_terms` (
  `doc_id` INTEGER NOT NULL,
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `term` TEXT COLLATE BINARY NOT NULL CONSTRAINT `ck_len_term` CHECK (length(`term`) <= 64),
  `field` INTEGER NOT NULL,
  PRIMARY KEY (`doc_id`, `term`, `field`),
  CONSTRAINT `fk_search_terms_doc` FOREIGN KEY (`doc_id`) REFERENCES `search_documents` (`id`) ON DELETE CASCADE
) STRICT;
CREATE TABLE `search_index_state` (
  `organization_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `version` INTEGER NOT NULL,
  `watermark` INTEGER NOT NULL,
  `rebuilt_at` INTEGER,
  CONSTRAINT `fk_search_state_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) STRICT;
CREATE TABLE `reel_moment_rejections` (
  `reel_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `in_pts_us` INTEGER NOT NULL,
  `out_pts_us` INTEGER NOT NULL,
  `rejected_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_rejected_by` CHECK (length(`rejected_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `video_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  PRIMARY KEY (`reel_id`, `in_pts_us`),
  CONSTRAINT `fk_reel_moment_rejections_reel` FOREIGN KEY (`reel_id`) REFERENCES `reel_projects` (`id`),
  CONSTRAINT `fk_reel_moment_rejections_user` FOREIGN KEY (`rejected_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_reel_moment_rejections_video` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `ck_reel_moment_rejection_window` CHECK (`out_pts_us` > `in_pts_us` AND `in_pts_us` >= 0)
) STRICT;
CREATE TABLE `reel_blocks` (
  `id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 120),
  `clips` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_clips` CHECK (json_valid(`clips`)),
  `clip_count` INTEGER NOT NULL,
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_reel_blocks_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_reel_blocks_video` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_reel_blocks_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_reel_blocks_count` CHECK (`clip_count` BETWEEN 1 AND 20),
  CONSTRAINT `ck_reel_blocks_clips` CHECK (json_type(`clips`) = 'array')
) STRICT;
CREATE TABLE `export_presets` (
  `id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `owner_user_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_owner_user_id` CHECK (length(`owner_user_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 80),
  `note` TEXT COLLATE NOCASE NOT NULL DEFAULT '' CONSTRAINT `ck_len_note` CHECK (length(`note`) <= 200),
  `spec` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_spec` CHECK (json_valid(`spec`)),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_export_presets_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_export_presets_owner` FOREIGN KEY (`owner_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_export_presets_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_export_presets_spec` CHECK (json_type(`spec`) = 'object')
) STRICT;
CREATE TABLE `assistant_plans` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `preview_role` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_preview_role` CHECK (length(`preview_role`) <= 16),
  `step` TEXT COLLATE NOCASE CONSTRAINT `ck_json_step` CHECK (json_valid(`step`)),
  `expires_at` INTEGER NOT NULL,
  `approved_at` INTEGER,
  CONSTRAINT `fk_assistant_plans_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_assistant_plans_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) STRICT;
CREATE TABLE `archive_bundles` (
  `id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `project_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_project_id` CHECK (length(`project_id`) <= 36),
  `subject_kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subject_kind` CHECK (length(`subject_kind`) <= 16),
  `subject_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subject_id` CHECK (length(`subject_id`) <= 36),
  `title` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_title` CHECK (length(`title`) <= 255),
  `video_ids` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_video_ids` CHECK (json_valid(`video_ids`)),
  `zip_asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_zip_asset_id` CHECK (length(`zip_asset_id`) <= 36),
  `manifest` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_manifest` CHECK (json_valid(`manifest`)),
  `audit_extract` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_audit_extract` CHECK (json_valid(`audit_extract`)),
  `audit_count` INTEGER NOT NULL,
  `byte_size` INTEGER NOT NULL,
  `sha256` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_sha256` CHECK (length(`sha256`) <= 64),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_archive_bundles_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_archive_bundles_asset` FOREIGN KEY (`zip_asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_archive_bundles_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_archive_bundles_kind` CHECK (`subject_kind` IN ('REEL', 'VIDEO', 'MATCH')),
  CONSTRAINT `ck_archive_bundles_videos` CHECK (json_type(`video_ids`) = 'array'),
  CONSTRAINT `ck_archive_bundles_manifest` CHECK (json_type(`manifest`) = 'object'),
  CONSTRAINT `ck_archive_bundles_audit` CHECK (json_type(`audit_extract`) = 'array')
) STRICT;
CREATE TABLE `music_beat_grids` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `brand_asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_brand_asset_id` CHECK (length(`brand_asset_id`) <= 36),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 12),
  `method` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_method` CHECK (length(`method`) <= 40),
  `tempo_bpm` REAL,
  `beats` TEXT COLLATE NOCASE CONSTRAINT `ck_json_beats` CHECK (json_valid(`beats`)),
  `beat_count` INTEGER,
  `duration_us` INTEGER,
  `periodicity` REAL,
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 64),
  `failure_detail` TEXT COLLATE NOCASE,
  `requested_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `finished_at` INTEGER,
  CONSTRAINT `fk_mbg_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_mbg_music` FOREIGN KEY (`brand_asset_id`) REFERENCES `brand_assets` (`id`),
  CONSTRAINT `fk_mbg_user` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_mbg_status` CHECK (`status` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED'))
) STRICT;
CREATE TABLE `org_templates` (
  `id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 80),
  `description` TEXT COLLATE NOCASE NOT NULL DEFAULT '' CONSTRAINT `ck_len_description` CHECK (length(`description`) <= 255),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 20),
  `spec` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_spec` CHECK (json_valid(`spec`)),
  `is_shared` INTEGER NOT NULL DEFAULT 1,
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `name`),
  CONSTRAINT `fk_org_templates_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_org_templates_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_org_templates_kind` CHECK (`kind` IN ('SPOTLIGHT', 'STYLE', 'BRANDING', 'FULL')),
  CONSTRAINT `ck_org_templates_spec` CHECK (json_type(`spec`) = 'object')
) STRICT;
CREATE TABLE `org_retention_policies` (
  `organization_id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `trash_days` INTEGER NOT NULL DEFAULT 30,
  `raw_footage_days` INTEGER,
  `rendered_reels_days` INTEGER,
  `audit_log_days` INTEGER NOT NULL DEFAULT 365,
  `auto_purge_enabled` INTEGER NOT NULL DEFAULT 0,
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_updated_by` CHECK (length(`updated_by`) <= 36),
  CONSTRAINT `fk_retention_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_retention_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_retention_trash_days` CHECK (`trash_days` >= 0 AND `trash_days` <= 3650),
  CONSTRAINT `ck_retention_audit_days` CHECK (`audit_log_days` >= 30 AND `audit_log_days` <= 3650)
) STRICT;
CREATE TABLE `subject_erasure_requests` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `subject_kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subject_kind` CHECK (length(`subject_kind`) <= 16),
  `subject_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_subject_id` CHECK (length(`subject_id`) <= 36),
  `subject_ref` TEXT COLLATE NOCASE CONSTRAINT `ck_len_subject_ref` CHECK (length(`subject_ref`) <= 128),
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `executed_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `summary` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_summary` CHECK (json_valid(`summary`)),
  CONSTRAINT `fk_erasure_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_erasure_user` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_erasure_kind` CHECK (`subject_kind` IN ('PLAYER', 'USER'))
) STRICT;
CREATE TABLE `formation_decisions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `kit_group` INTEGER NOT NULL,
  `period` TEXT COLLATE NOCASE NOT NULL DEFAULT 'FULL' CONSTRAINT `ck_len_period` CHECK (length(`period`) <= 8),
  `formation_name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_formation_name` CHECK (length(`formation_name`) <= 16),
  `state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'INFERRED' CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 16),
  `decided_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `reason` TEXT COLLATE NOCASE,
  `decided_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_formation_decisions_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_formation_decisions_video` FOREIGN KEY (`video_id`) REFERENCES `video_sources` (`id`),
  CONSTRAINT `fk_formation_decisions_user` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_formation_decisions_state` CHECK (`state` IN ('INFERRED', 'CONFIRMED')),
  CONSTRAINT `ck_formation_decisions_period` CHECK (`period` IN ('FULL', 'H1', 'H2'))
) STRICT;
CREATE TABLE `player_profile_details` (
  `player_id` TEXT COLLATE NOCASE PRIMARY KEY NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `height_cm` INTEGER,
  `weight_kg` REAL,
  `photo_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_photo_asset_id` CHECK (length(`photo_asset_id`) <= 36),
  `strengths` TEXT COLLATE NOCASE CONSTRAINT `ck_json_strengths` CHECK (json_valid(`strengths`)),
  `summary` TEXT COLLATE NOCASE,
  `club_name` TEXT COLLATE NOCASE CONSTRAINT `ck_len_club_name` CHECK (length(`club_name`) <= 255),
  `league` TEXT COLLATE NOCASE CONSTRAINT `ck_len_league` CHECK (length(`league`) <= 255),
  `international_country_code` TEXT COLLATE BINARY CONSTRAINT `ck_len_international_country_code` CHECK (length(`international_country_code`) <= 3),
  `international_caps` INTEGER,
  `international_goals` INTEGER,
  `updated_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_updated_by` CHECK (length(`updated_by`) <= 36),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_ppd_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_ppd_photo` FOREIGN KEY (`photo_asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fk_ppd_country` FOREIGN KEY (`international_country_code`) REFERENCES `countries` (`code`),
  CONSTRAINT `fk_ppd_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_ppd_height` CHECK (`height_cm` IS NULL OR `height_cm` BETWEEN 100 AND 250),
  CONSTRAINT `ck_ppd_weight` CHECK (`weight_kg` IS NULL OR `weight_kg` BETWEEN 30 AND 200)
) STRICT;
CREATE TABLE `wallet_ledger` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_kind` CHECK (`kind` IN ('PURCHASE', 'FREE_GRANT', 'SPEND', 'REFUND', 'ADJUSTMENT', 'EXPIRY')),
  `amount` INTEGER NOT NULL,
  `balance_after` INTEGER NOT NULL CHECK (`balance_after` >= 0),
  `job_type` TEXT COLLATE NOCASE CONSTRAINT `ck_len_job_type` CHECK (length(`job_type`) <= 64),
  `job_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_job_id` CHECK (length(`job_id`) <= 36),
  `idempotency_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_idempotency_key` CHECK (length(`idempotency_key`) <= 255),
  `invoice_ref` TEXT COLLATE NOCASE CONSTRAINT `ck_len_invoice_ref` CHECK (length(`invoice_ref`) <= 255),
  `reason` TEXT COLLATE NOCASE CONSTRAINT `ck_len_reason` CHECK (length(`reason`) <= 500),
  `actor_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_actor_id` CHECK (length(`actor_id`) <= 36),
  `expires_at` INTEGER,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `idempotency_key`),
  CONSTRAINT `fk_wallet_ledger_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CHECK (`amount` <> 0),
  CHECK ((`kind` IN ('SPEND','EXPIRY') AND `amount` < 0)
      OR (`kind` IN ('PURCHASE','FREE_GRANT','REFUND') AND `amount` > 0)
      OR `kind` = 'ADJUSTMENT'),
  CHECK ((`kind` = 'SPEND' AND `job_type` IS NOT NULL AND `job_id` IS NOT NULL)
      OR (`kind` <> 'SPEND')),
  CHECK ((`kind` = 'PURCHASE' AND `invoice_ref` IS NOT NULL) OR (`kind` <> 'PURCHASE'))
) STRICT;
CREATE TABLE `wallet_pack_requests` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `pack_code` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_pack_code` CHECK (`pack_code` IN ('FREE', 'STARTER', 'CLUB', 'ACADEMY', 'SEASON')),
  `currency` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_currency` CHECK (length(`currency`) <= 3),
  `amount_minor` INTEGER NOT NULL CHECK (`amount_minor` > 0),
  `tokens` INTEGER NOT NULL CHECK (`tokens` > 0),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'REQUESTED' CONSTRAINT `ck_enum_status` CHECK (`status` IN ('REQUESTED', 'INVOICED', 'PAID', 'CANCELLED')),
  `invoice_ref` TEXT COLLATE NOCASE CONSTRAINT `ck_len_invoice_ref` CHECK (length(`invoice_ref`) <= 255),
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_wallet_pack_requests_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) STRICT;
CREATE TABLE `wallet_free_grants` (
  `organization_id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `granted_tokens` INTEGER NOT NULL DEFAULT 100,
  `email` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_email` CHECK (length(`email`) <= 255),
  `granted_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_granted_by` CHECK (length(`granted_by`) <= 36),
  `granted_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `expires_at` INTEGER NOT NULL,
  CONSTRAINT `fk_wallet_free_grants_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) STRICT;
CREATE TABLE `ai_analyst_assessments` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'DRAFT' CONSTRAINT `ck_enum_status` CHECK (`status` IN ('DRAFT', 'PUBLISHED')),
  `language` TEXT COLLATE NOCASE NOT NULL DEFAULT 'en' CONSTRAINT `ck_len_language` CHECK (length(`language`) <= 2),
  `input_snapshot` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_input_snapshot` CHECK (json_valid(`input_snapshot`)),
  `output` TEXT COLLATE NOCASE CONSTRAINT `ck_json_output` CHECK (json_valid(`output`)),
  `model` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_model` CHECK (length(`model`) <= 128),
  `prompt_version` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_prompt_version` CHECK (length(`prompt_version`) <= 32),
  `post_check` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_post_check` CHECK (json_valid(`post_check`)),
  `stale` INTEGER NOT NULL DEFAULT 0,
  `not_enough_data_reason` TEXT COLLATE NOCASE CONSTRAINT `ck_len_not_enough_data_reason` CHECK (length(`not_enough_data_reason`) <= 500),
  `failure` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure` CHECK (length(`failure`) <= 500),
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `consent_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_consent_by` CHECK (length(`consent_by`) <= 36),
  `consent_at` INTEGER NOT NULL,
  `published_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_published_by` CHECK (length(`published_by`) <= 36),
  `published_at` INTEGER,
  `version` INTEGER NOT NULL DEFAULT 1,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CONSTRAINT `fk_ai_analyst_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) STRICT;
CREATE TABLE `scouting_packs` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `reel_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `reel_source` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_reel_source` CHECK (`reel_source` IN ('SINGLE_MATCH', 'CROSS_MATCH')),
  `state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'CREATED' CONSTRAINT `ck_enum_state` CHECK (`state` IN ('CREATED', 'READY', 'FAILED')),
  `manifest` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_manifest` CHECK (json_valid(`manifest`)),
  `cost_tokens` INTEGER NOT NULL DEFAULT 10,
  `zip_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_zip_asset_id` CHECK (length(`zip_asset_id`) <= 36),
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `completed_at` INTEGER,
  CONSTRAINT `fk_scouting_packs_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) STRICT;
CREATE TABLE `webauthn_credentials` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `credential_id` TEXT COLLATE NOCASE NOT NULL UNIQUE CONSTRAINT `ck_len_credential_id` CHECK (length(`credential_id`) <= 255),
  `public_key` TEXT COLLATE NOCASE NOT NULL,
  `counter` INTEGER NOT NULL DEFAULT 0,
  `transports` TEXT COLLATE NOCASE CONSTRAINT `ck_json_transports` CHECK (json_valid(`transports`)),
  `device_name` TEXT COLLATE NOCASE CONSTRAINT `ck_len_device_name` CHECK (length(`device_name`) <= 80),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `last_used_at` INTEGER,
  CONSTRAINT `fk_webauthn_credentials_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) STRICT;
CREATE TABLE `webauthn_challenges` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `purpose` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_purpose` CHECK (`purpose` IN ('register', 'login')),
  `user_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `email` TEXT COLLATE NOCASE CONSTRAINT `ck_len_email` CHECK (length(`email`) <= 255),
  `challenge` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_challenge` CHECK (length(`challenge`) <= 255),
  `expires_at` INTEGER NOT NULL,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `bank_accounts` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `currency` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_currency` CHECK (length(`currency`) <= 3),
  `account_name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_account_name` CHECK (length(`account_name`) <= 255),
  `bank_name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_bank_name` CHECK (length(`bank_name`) <= 255),
  `account_number` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_account_number` CHECK (length(`account_number`) <= 64),
  `swift_iban` TEXT COLLATE NOCASE CONSTRAINT `ck_len_swift_iban` CHECK (length(`swift_iban`) <= 64),
  `is_active` INTEGER NOT NULL DEFAULT 1,
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`currency`),
  CHECK (`currency` IN ('NGN','USD'))
) STRICT;
CREATE TABLE `bank_transfer_orders` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `plan_code` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_plan_code` CHECK (length(`plan_code`) <= 32),
  `period_months` INTEGER NOT NULL,
  `amount_minor` INTEGER NOT NULL CHECK (`amount_minor` > 0),
  `currency` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_currency` CHECK (length(`currency`) <= 3),
  `reference` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reference` CHECK (length(`reference`) <= 32),
  `bank_account_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_bank_account_id` CHECK (length(`bank_account_id`) <= 36),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'ORDERED' CONSTRAINT `ck_enum_status` CHECK (`status` IN ('ORDERED', 'AWAITING_CONFIRMATION', 'CONFIRMED', 'REJECTED', 'PARTIAL', 'REFUNDED')),
  `amount_received_minor` INTEGER NOT NULL DEFAULT 0 CHECK (`amount_received_minor` >= 0),
  `amount_refunded_minor` INTEGER CHECK (`amount_refunded_minor` IS NULL OR `amount_refunded_minor` >= 0),
  `tokens_granted` INTEGER NOT NULL CHECK (`tokens_granted` > 0),
  `subscription_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_subscription_id` CHECK (length(`subscription_id`) <= 36),
  `renews_subscription_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_renews_subscription_id` CHECK (length(`renews_subscription_id`) <= 36),
  `expires_at` INTEGER NOT NULL,
  `proof_storage_key` TEXT COLLATE NOCASE CONSTRAINT `ck_len_proof_storage_key` CHECK (length(`proof_storage_key`) <= 512),
  `proof_filename` TEXT COLLATE NOCASE CONSTRAINT `ck_len_proof_filename` CHECK (length(`proof_filename`) <= 255),
  `proof_content_type` TEXT COLLATE NOCASE CONSTRAINT `ck_len_proof_content_type` CHECK (length(`proof_content_type`) <= 128),
  `proof_size_bytes` INTEGER CHECK (`proof_size_bytes` IS NULL OR `proof_size_bytes` > 0),
  `proof_sha256` TEXT COLLATE NOCASE CONSTRAINT `ck_len_proof_sha256` CHECK (length(`proof_sha256`) <= 64),
  `proof_uploaded_at` INTEGER,
  `proof_note` TEXT COLLATE NOCASE CONSTRAINT `ck_len_proof_note` CHECK (length(`proof_note`) <= 500),
  `confirmed_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_confirmed_by` CHECK (length(`confirmed_by`) <= 36),
  `confirmed_at` INTEGER,
  `bank_reference` TEXT COLLATE NOCASE CONSTRAINT `ck_len_bank_reference` CHECK (length(`bank_reference`) <= 255),
  `reject_reason` TEXT COLLATE NOCASE CONSTRAINT `ck_len_reject_reason` CHECK (length(`reject_reason`) <= 500),
  `refund_reason` TEXT COLLATE NOCASE CONSTRAINT `ck_len_refund_reason` CHECK (length(`refund_reason`) <= 500),
  `created_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`reference`),
  CONSTRAINT `fk_bank_transfer_orders_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_bank_transfer_orders_bank_account` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`),
  CONSTRAINT `fk_bank_transfer_orders_subscription` FOREIGN KEY (`subscription_id`) REFERENCES `subscriptions` (`id`),
  CONSTRAINT `fk_bank_transfer_orders_renews` FOREIGN KEY (`renews_subscription_id`) REFERENCES `subscriptions` (`id`),
  CHECK (`currency` IN ('NGN','USD')),
  CHECK (`plan_code` IN ('STARTER','CLUB','ACADEMY','SEASON')),
  CHECK (`period_months` IN (1, 12)),
  CHECK (`amount_received_minor` <= `amount_minor`),
  CHECK ((`status` = 'CONFIRMED' AND `confirmed_by` IS NOT NULL AND `confirmed_at` IS NOT NULL AND `amount_received_minor` = `amount_minor`)
      OR (`status` <> 'CONFIRMED')),
  CHECK ((`status` = 'REJECTED' AND `reject_reason` IS NOT NULL) OR (`status` <> 'REJECTED')),
  CHECK ((`status` = 'REFUNDED' AND `refund_reason` IS NOT NULL) OR (`status` <> 'REFUNDED'))
) STRICT;
CREATE TABLE `bank_transfer_reference_seq` (
  `year` INTEGER PRIMARY KEY,
  `next_seq` INTEGER NOT NULL DEFAULT 0 CHECK (`next_seq` >= 0)
) STRICT;
CREATE TABLE `job_tickets` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `job_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_job_type` CHECK (`job_type` IN ('ANALYSIS', 'REEL_RENDER', 'PLAYER_REPORT', 'EXPORT_PACK', 'AI_ANALYSIS')),
  `job_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_job_id` CHECK (length(`job_id`) <= 36),
  `amount` INTEGER NOT NULL CHECK (`amount` > 0),
  `source` TEXT COLLATE NOCASE NOT NULL DEFAULT 'ONLINE' CONSTRAINT `ck_enum_source` CHECK (`source` IN ('ONLINE', 'OFFLINE')),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_state` CHECK (`state` IN ('CHARGED', 'OWED', 'REFUNDED')),
  `ledger_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_ledger_id` CHECK (length(`ledger_id`) <= 36),
  `requested_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `spent_at` INTEGER,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `job_type`, `job_id`),
  CONSTRAINT `fk_job_tickets_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CHECK ((`state` = 'CHARGED' AND `ledger_id` IS NOT NULL) OR (`state` <> 'CHARGED')),
  CHECK ((`source` = 'OFFLINE' AND `spent_at` IS NOT NULL) OR (`source` = 'ONLINE'))
) STRICT;
CREATE TABLE `linked_job_tickets` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `job_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_job_type` CHECK (`job_type` IN ('ANALYSIS', 'REEL_RENDER', 'PLAYER_REPORT', 'EXPORT_PACK', 'AI_ANALYSIS')),
  `job_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_job_id` CHECK (length(`job_id`) <= 36),
  `amount` INTEGER NOT NULL CHECK (`amount` > 0),
  `source` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_source` CHECK (`source` IN ('ONLINE', 'OFFLINE')),
  `state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'ACTIVE' CONSTRAINT `ck_enum_state` CHECK (`state` IN ('ACTIVE', 'SETTLED', 'REFUND_PENDING', 'REFUNDED')),
  `ticket_token` TEXT COLLATE NOCASE,
  `actor_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_actor_id` CHECK (length(`actor_id`) <= 36),
  `spent_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `settled_at` INTEGER,
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `job_type`, `job_id`),
  CONSTRAINT `fk_linked_job_tickets_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CHECK ((`source` = 'ONLINE' AND `ticket_token` IS NOT NULL) OR (`source` = 'OFFLINE'))
) STRICT;
CREATE TABLE `central_links` (
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `central_url` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_central_url` CHECK (length(`central_url`) <= 255),
  `refresh_sealed` TEXT COLLATE NOCASE NOT NULL,
  `licence_token` TEXT COLLATE NOCASE,
  `licence_expires_at` INTEGER,
  `linked_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  PRIMARY KEY (`user_id`, `organization_id`),
  CONSTRAINT `fk_central_links_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_central_links_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) STRICT;
