CREATE VIEW `v_player_identity` AS WITH RECURSIVE chain (player_id, current_id, next_id, hops) AS (
  SELECT id, id, merged_into_player_id, 0 FROM players
  UNION ALL
  SELECT c.player_id, p.id, p.merged_into_player_id, c.hops + 1
  FROM chain c JOIN players p ON p.id = c.next_id
  WHERE c.hops < 32
)
SELECT p.id AS player_id,
       p.canonical_otsi_id AS own_canonical_otsi_id,
       p.canonical_state AS own_state,
       s.id AS resolved_player_id,
       s.canonical_otsi_id AS canonical_otsi_id,
       s.canonical_state AS resolved_state,
       s.display_name AS display_name,
       p.created_by_organization_id
FROM chain c
JOIN players p ON p.id = c.player_id
JOIN players s ON s.id = c.current_id
WHERE c.next_id IS NULL;
CREATE VIEW `v_track_current_identity` AS SELECT d.track_id, d.id AS decision_id, d.state, d.player_id, d.basis, d.decided_by, d.decided_at
FROM track_identity_decisions d
WHERE NOT EXISTS (SELECT 1 FROM track_identity_decisions n WHERE n.supersedes_id = d.id);
CREATE VIEW `v_track_link_current` AS SELECT l.id AS link_id, l.run_id, l.track_a_id, l.track_b_id, l.score, l.crosses_cut, l.gap_us,
       d.id AS decision_id, COALESCE(d.state, 'PROPOSED') AS state, d.decided_by, d.decided_at
FROM track_links l
LEFT JOIN track_link_decisions d ON d.link_id = l.id
  AND NOT EXISTS (SELECT 1 FROM track_link_decisions n WHERE n.supersedes_id = d.id);
CREATE VIEW `v_run_team_current` AS SELECT a.run_id, a.kit_group, a.club_id, a.id AS assignment_id, a.decided_by, a.decided_at
FROM run_team_assignments a WHERE NOT EXISTS (SELECT 1 FROM run_team_assignments n WHERE n.supersedes_id = a.id);
CREATE VIEW `v_track_jersey_current` AS SELECT d.track_id, d.id AS decision_id, d.state, d.number, d.decided_by, d.decided_at
FROM jersey_number_decisions d WHERE NOT EXISTS (SELECT 1 FROM jersey_number_decisions n WHERE n.supersedes_id = d.id);
CREATE TRIGGER `trg_projects_update` AFTER UPDATE ON `projects`
WHEN NEW.`updated_at` = OLD.`updated_at`
BEGIN
  UPDATE `projects` SET `updated_at` = MAX((CAST(unixepoch('subsec')*1000 AS INTEGER)), OLD.`updated_at`+1),
    `version` = OLD.`version`+1 WHERE `id` = NEW.`id`;
END;
