WHEN NEW.`updated_at` = OLD.`updated_at`
BEGIN
  UPDATE `bank_accounts` SET `updated_at` = MAX((CAST(unixepoch('subsec')*1000 AS INTEGER)), OLD.`updated_at`+1)
  WHERE `id` = NEW.`id`;
