WHEN NEW.`updated_at` = OLD.`updated_at`
BEGIN
  UPDATE `central_links` SET `updated_at` = MAX((CAST(unixepoch('subsec')*1000 AS INTEGER)), OLD.`updated_at`+1)
  WHERE `user_id` = NEW.`user_id` AND `organization_id` = NEW.`organization_id`;
END;

