UPDATE `players` SET `canonical_state` = CASE `canonical_state` WHEN 'PENDING' THEN 'PROVISIONAL' WHEN 'VERIFIED' THEN 'REGISTERED' ELSE `canonical_state` END;
UPDATE `reel_projects` AS r
   SET `removed_at` = COALESCE((SELECT MAX(a.`occurred_at`) FROM `audit_events` a WHERE a.`entity_id` = r.`id` AND a.`action` = 'reel.deleted'), r.`updated_at`),
       `removed_by` = COALESCE((SELECT a.`actor_id` FROM `audit_events` a WHERE a.`entity_id` = r.`id` AND a.`action` = 'reel.deleted' AND a.`actor_id` IS NOT NULL
                                   ORDER BY a.`id` DESC LIMIT 1), r.`created_by`),
       `status` = COALESCE((SELECT json_extract(a.`before_state`, '$.status') FROM `audit_events` a
                               WHERE a.`entity_id` = r.`id` AND a.`action` = 'reel.deleted'
                                 AND json_extract(a.`before_state`, '$.status') IN ('DRAFT', 'READY', 'PUBLISHED', 'BLOCKED')
                               ORDER BY a.`id` DESC LIMIT 1), 'READY')
 WHERE r.`status` = 'ARCHIVED';
INSERT INTO `library_deletions` (`id`, `organization_id`, `item_kind`, `item_id`, `title`, `deleted_by`, `deleted_at`)
SELECT lower(substr(hex(randomblob(4)),1,8) || '-' || substr(hex(randomblob(2)),1,4) || '-4' || substr(hex(randomblob(2)),2,3) || '-' || substr('ab89', 1 + abs(random()) % 4, 1) || substr(hex(randomblob(2)),2,3) || '-' || substr(hex(randomblob(6)),1,12)), p.`organization_id`, 'project', p.`id`, p.`name`, p.`removed_by`, p.`removed_at` FROM `projects` p WHERE p.`removed_at` IS NOT NULL;
INSERT INTO `library_deletions` (`id`, `organization_id`, `item_kind`, `item_id`, `title`, `deleted_by`, `deleted_at`)
SELECT lower(substr(hex(randomblob(4)),1,8) || '-' || substr(hex(randomblob(2)),1,4) || '-4' || substr(hex(randomblob(2)),2,3) || '-' || substr('ab89', 1 + abs(random()) % 4, 1) || substr(hex(randomblob(2)),2,3) || '-' || substr(hex(randomblob(6)),1,12)), v.`organization_id`, 'video', v.`id`, COALESCE(v.`title`, v.`original_filename`, 'Video'), v.`removed_by`, v.`removed_at`
  FROM `video_sources` v WHERE v.`removed_at` IS NOT NULL AND v.`state` = 'INGESTED' AND v.`removed_by` IS NOT NULL;
INSERT INTO `library_deletions` (`id`, `organization_id`, `item_kind`, `item_id`, `title`, `deleted_by`, `deleted_at`)
SELECT lower(substr(hex(randomblob(4)),1,8) || '-' || substr(hex(randomblob(2)),1,4) || '-4' || substr(hex(randomblob(2)),2,3) || '-' || substr('ab89', 1 + abs(random()) % 4, 1) || substr(hex(randomblob(2)),2,3) || '-' || substr(hex(randomblob(6)),1,12)), m.`organization_id`, 'match', m.`id`, COALESCE((h.`canonical_name` || ' v ' || a.`canonical_name`), m.`competition`, 'Match'), m.`removed_by`, m.`removed_at`
  FROM `matches` m LEFT JOIN `clubs` h ON h.`id` = m.`home_club_id` LEFT JOIN `clubs` a ON a.`id` = m.`away_club_id` WHERE m.`removed_at` IS NOT NULL;
INSERT INTO `library_deletions` (`id`, `organization_id`, `item_kind`, `item_id`, `title`, `deleted_by`, `deleted_at`)
SELECT lower(substr(hex(randomblob(4)),1,8) || '-' || substr(hex(randomblob(2)),1,4) || '-4' || substr(hex(randomblob(2)),2,3) || '-' || substr('ab89', 1 + abs(random()) % 4, 1) || substr(hex(randomblob(2)),2,3) || '-' || substr(hex(randomblob(6)),1,12)), r.`organization_id`, 'reel', r.`id`, r.`name`, r.`removed_by`, r.`removed_at` FROM `reel_projects` r WHERE r.`removed_at` IS NOT NULL;
INSERT INTO `library_deletions` (`id`, `organization_id`, `item_kind`, `item_id`, `title`, `deleted_by`, `deleted_at`)
SELECT lower(substr(hex(randomblob(4)),1,8) || '-' || substr(hex(randomblob(2)),1,4) || '-4' || substr(hex(randomblob(2)),2,3) || '-' || substr('ab89', 1 + abs(random()) % 4, 1) || substr(hex(randomblob(2)),2,3) || '-' || substr(hex(randomblob(6)),1,12)), j.`organization_id`, 'render', j.`id`, (r.`name` || ' · rendered'), j.`removed_by`, j.`removed_at`
  FROM `render_jobs` j JOIN `reel_projects` r ON r.`id` = j.`reel_id` WHERE j.`removed_at` IS NOT NULL AND r.`removed_at` IS NULL;
INSERT INTO `library_deletion_items` (`deletion_id`, `item_kind`, `item_id`, `prior`)
SELECT d.`id`, d.`item_kind`, d.`item_id`, json_object() FROM `library_deletions` d;
UPDATE `reel_projects`
   SET `best_moments_rule_version` = CAST(`best_moments_rule_version` AS TEXT)
 WHERE `best_moments_rule_version` IS NOT NULL;
